window.BUNPOPANDA_GRAMMAR_SEED = [{"id":1,"expression":"です","meaning":"to be (polite)","category":"Basics","format":"Noun / な-adjective + です","usages":[{"usage":"Make a polite statement","japanese":"私(わたし)は学生(がくせい)です。","reading":"わたしは がくせいです。","english":"I am a student."},{"usage":"State a quality politely","japanese":"この町(まち)は静(しず)かです。","reading":"このまちは しずかです。","english":"This town is quiet."}],"level":"N5"},{"id":2,"expression":"ではありません","meaning":"is not (polite)","category":"Basics","format":"Noun / な-adjective + ではありません","usages":[{"usage":"Negate a noun statement","japanese":"今日(きょう)は休(やす)みではありません。","reading":"きょうは やすみではありません。","english":"Today is not a day off."},{"usage":"Negate a な-adjective","japanese":"ここは便利(べんり)ではありません。","reading":"ここは べんりではありません。","english":"This place is not convenient."}],"level":"N5"},{"id":3,"expression":"でした","meaning":"was (polite)","category":"Basics","format":"Noun / な-adjective + でした","usages":[{"usage":"Speak about a past state","japanese":"昨日(きのう)は雨(あめ)でした。","reading":"きのうは あめでした。","english":"It was rainy yesterday."},{"usage":"Describe a past な-adjective state","japanese":"昨日(きのう)は静(しず)かでした。","reading":"きのうは しずかでした。","english":"It was quiet yesterday."}],"level":"N5"},{"id":4,"expression":"ではありませんでした","meaning":"was not (polite)","category":"Basics","format":"Noun / な-adjective + ではありませんでした","usages":[{"usage":"Negate a past noun statement","japanese":"昨日(きのう)は休日(きゅうじつ)ではありませんでした。","reading":"きのうは きゅうじつではありませんでした。","english":"Yesterday was not a holiday."}],"level":"N5"},{"id":5,"expression":"は","meaning":"topic marker","category":"Particles","format":"Topic + は + comment","usages":[{"usage":"Introduce the topic","japanese":"私(わたし)は会社員(かいしゃいん)です。","reading":"わたしは かいしゃいんです。","english":"I am an office worker."},{"usage":"Contrast two things","japanese":"水(みず)は飲(の)みますが、コーヒーは飲(の)みません。","reading":"みずは のみますが、コーヒーは のみません。","english":"I drink water, but not coffee."}],"level":"N5"},{"id":6,"expression":"が","meaning":"subject marker","category":"Particles","format":"Subject + が + predicate","usages":[{"usage":"Mark the subject","japanese":"猫(ねこ)がいます。","reading":"ねこが います。","english":"There is a cat."},{"usage":"Mark what someone likes","japanese":"音楽(おんがく)が好(す)きです。","reading":"おんがくが すきです。","english":"I like music."}],"level":"N5"},{"id":7,"expression":"を","meaning":"direct-object marker","category":"Particles","format":"Object + を + transitive verb","usages":[{"usage":"Mark an object","japanese":"本(ほん)を読(よ)みます。","reading":"ほんを よみます。","english":"I read a book."},{"usage":"Mark a path traveled","japanese":"公園(こうえん)を歩(ある)きます。","reading":"こうえんを あるきます。","english":"I walk through the park."}],"level":"N5"},{"id":8,"expression":"に","meaning":"time, destination, recipient","category":"Particles","format":"Time / destination / recipient + に","usages":[{"usage":"Mark a specific time","japanese":"七時(しちじ)に起(お)きます。","reading":"しちじに おきます。","english":"I wake up at seven."},{"usage":"Mark a destination","japanese":"学校(がっこう)に行(い)きます。","reading":"がっこうに いきます。","english":"I go to school."}],"level":"N5"},{"id":9,"expression":"で","meaning":"place or means","category":"Particles","format":"Place / means + で + action","usages":[{"usage":"Mark the location of an action","japanese":"図書館(としょかん)で勉強(べんきょう)します。","reading":"としょかんで べんきょうします。","english":"I study at the library."},{"usage":"Mark a means of transport","japanese":"電車(でんしゃ)で行(い)きます。","reading":"でんしゃで いきます。","english":"I go by train."}],"level":"N5"},{"id":10,"expression":"へ","meaning":"direction marker","category":"Particles","format":"Destination + へ + movement verb","usages":[{"usage":"Show direction of movement","japanese":"日本(にほん)へ行(い)きます。","reading":"にほんへ いきます。","english":"I am going to Japan."}],"level":"N5"},{"id":11,"expression":"の","meaning":"possession or modification","category":"Particles","format":"Noun A + の + Noun B","usages":[{"usage":"Show possession","japanese":"これは私(わたし)の鞄(かばん)です。","reading":"これは わたしの かばんです。","english":"This is my bag."},{"usage":"Link two nouns","japanese":"日本語(にほんご)の先生(せんせい)です。","reading":"にほんごの せんせいです。","english":"I am a Japanese teacher."}],"level":"N5"},{"id":12,"expression":"も","meaning":"also, too","category":"Particles","format":"Noun + も","usages":[{"usage":"Add another item","japanese":"私(わたし)も行(い)きます。","reading":"わたしも いきます。","english":"I am going too."}],"level":"N5"},{"id":13,"expression":"と","meaning":"and / with","category":"Particles","format":"Noun + と + Noun; Person + と + verb","usages":[{"usage":"List nouns exhaustively","japanese":"りんごとバナナを買(か)います。","reading":"りんごと バナナを かいます。","english":"I buy apples and bananas."},{"usage":"Do something with someone","japanese":"友達(ともだち)と話(はな)します。","reading":"ともだちと はなします。","english":"I talk with a friend."}],"level":"N5"},{"id":14,"expression":"や","meaning":"and, among others","category":"Particles","format":"Noun + や + Noun + など","usages":[{"usage":"Give non-exhaustive examples","japanese":"机(つくえ)の上(うえ)に本(ほん)や雑誌(ざっし)があります。","reading":"つくえの うえに ほんや ざっしが あります。","english":"There are books, magazines, and such on the desk."}],"level":"N5"},{"id":15,"expression":"か","meaning":"question marker / or","category":"Particles","format":"Sentence + か; Noun + か + Noun","usages":[{"usage":"Ask a question","japanese":"明日(あした)は暇(ひま)ですか。","reading":"あしたは ひまですか。","english":"Are you free tomorrow?"},{"usage":"Offer alternatives","japanese":"お茶(ちゃ)か水(みず)をください。","reading":"おちゃか みずを ください。","english":"Tea or water, please."}],"level":"N5"},{"id":16,"expression":"ね","meaning":"agreement, softening","category":"Particles","format":"Sentence + ね","usages":[{"usage":"Seek shared agreement","japanese":"今日(きょう)は寒(さむ)いですね。","reading":"きょうは さむいですね。","english":"It's cold today, isn't it?"}],"level":"N5"},{"id":17,"expression":"よ","meaning":"emphasis, new information","category":"Particles","format":"Sentence + よ","usages":[{"usage":"Tell the listener something","japanese":"この店(みせ)は安(やす)いですよ。","reading":"このみせは やすいですよ。","english":"This shop is inexpensive, you know."}],"level":"N5"},{"id":18,"expression":"から","meaning":"from / because","category":"Particles","format":"Place / time + から; Clause + から","usages":[{"usage":"Mark a starting point","japanese":"九時(くじ)から働(はたら)きます。","reading":"くじから はたらきます。","english":"I work from nine."},{"usage":"Give a reason","japanese":"雨(あめ)ですから、行(い)きません。","reading":"あめですから、いきません。","english":"Because it's raining, I won't go."}],"level":"N5"},{"id":19,"expression":"まで","meaning":"until / as far as","category":"Particles","format":"Time / place + まで","usages":[{"usage":"Mark an endpoint in time","japanese":"五時(ごじ)まで勉強(べんきょう)します。","reading":"ごじまで べんきょうします。","english":"I study until five."},{"usage":"Mark an endpoint in space","japanese":"駅(えき)まで歩(ある)きます。","reading":"えきまで あるきます。","english":"I walk as far as the station."}],"level":"N5"},{"id":20,"expression":"より","meaning":"than (comparison)","category":"Comparison","format":"Noun A + より + Noun B + adjective","usages":[{"usage":"Compare two things","japanese":"今日(きょう)は昨日(きのう)より暑(あつ)いです。","reading":"きょうは きのうより あついです。","english":"Today is hotter than yesterday."}],"level":"N5"},{"id":21,"expression":"のほうが","meaning":"more ... than","category":"Comparison","format":"A より B のほうが + adjective","usages":[{"usage":"Prefer or compare B over A","japanese":"犬(いぬ)より猫(ねこ)のほうが好(す)きです。","reading":"いぬより ねこのほうが すきです。","english":"I like cats more than dogs."}],"level":"N5"},{"id":22,"expression":"いちばん","meaning":"the most","category":"Comparison","format":"Group + で + Noun + がいちばん + adjective","usages":[{"usage":"Express a superlative","japanese":"果物(くだもの)で桃(もも)がいちばん好(す)きです。","reading":"くだもので ももが いちばん すきです。","english":"Of fruits, I like peaches the most."}],"level":"N5"},{"id":23,"expression":"これ・それ・あれ","meaning":"this / that / that over there","category":"Demonstratives","format":"これ / それ / あれ + は + ...","usages":[{"usage":"Refer to an object without a noun","japanese":"これは何(なん)ですか。","reading":"これは なんですか。","english":"What is this?"},{"usage":"Refer to an object near the listener","japanese":"それは私(わたし)のです。","reading":"それは わたしのです。","english":"That is mine."}],"level":"N5"},{"id":24,"expression":"この・その・あの","meaning":"this / that + noun","category":"Demonstratives","format":"この / その / あの + Noun","usages":[{"usage":"Modify a noun by location","japanese":"この本(ほん)は面白(おもしろ)いです。","reading":"このほんは おもしろいです。","english":"This book is interesting."}],"level":"N5"},{"id":25,"expression":"ここ・そこ・あそこ","meaning":"here / there / over there","category":"Demonstratives","format":"ここ / そこ / あそこ + に / で / は ...","usages":[{"usage":"Refer to a place","japanese":"ここで待(ま)ってください。","reading":"ここで まってください。","english":"Please wait here."}],"level":"N5"},{"id":26,"expression":"どこ・どれ・どの","meaning":"where / which","category":"Questions","format":"どこ; どれ; どの + Noun","usages":[{"usage":"Ask about a place","japanese":"駅(えき)はどこですか。","reading":"えきは どこですか。","english":"Where is the station?"},{"usage":"Ask which item","japanese":"どの靴(くつ)が好(す)きですか。","reading":"どのくつが すきですか。","english":"Which shoes do you like?"}],"level":"N5"},{"id":27,"expression":"何・誰・いつ","meaning":"what / who / when","category":"Questions","format":"何(なに / なん); 誰(だれ); いつ","usages":[{"usage":"Ask for information","japanese":"誰(だれ)が来(き)ますか。","reading":"だれが きますか。","english":"Who is coming?"},{"usage":"Ask about time","japanese":"いつ帰(かえ)りますか。","reading":"いつ かえりますか。","english":"When are you going home?"}],"level":"N5"},{"id":28,"expression":"どう・どうして","meaning":"how / why","category":"Questions","format":"どう + ...; どうして + ...","usages":[{"usage":"Ask how something is","japanese":"日本(にほん)の生活(せいかつ)はどうですか。","reading":"にほんの せいかつは どうですか。","english":"How is life in Japan?"},{"usage":"Ask the reason","japanese":"どうして遅(おく)れましたか。","reading":"どうして おくれましたか。","english":"Why were you late?"}],"level":"N5"},{"id":29,"expression":"あります","meaning":"there is (inanimate)","category":"Existence","format":"Place + に + Thing + があります","usages":[{"usage":"State that something exists","japanese":"机(つくえ)の下(した)に箱(はこ)があります。","reading":"つくえの したに はこが あります。","english":"There is a box under the desk."}],"level":"N5"},{"id":30,"expression":"います","meaning":"there is (animate)","category":"Existence","format":"Place + に + Person / animal + がいます","usages":[{"usage":"State that someone exists","japanese":"庭(にわ)に犬(いぬ)がいます。","reading":"にわに いぬが います。","english":"There is a dog in the garden."}],"level":"N5"},{"id":31,"expression":"ます","meaning":"polite nonpast verb","category":"Verb Forms","format":"Verb ます-stem + ます","usages":[{"usage":"Talk about present habits","japanese":"毎朝(まいあさ)走(はし)ります。","reading":"まいあさ はしります。","english":"I run every morning."},{"usage":"Talk about future actions","japanese":"明日(あした)出(で)かけます。","reading":"あした でかけます。","english":"I'll go out tomorrow."}],"level":"N5"},{"id":32,"expression":"ません","meaning":"polite nonpast negative","category":"Verb Forms","format":"Verb ます-stem + ません","usages":[{"usage":"Say an action does not happen","japanese":"肉(にく)を食(た)べません。","reading":"にくを たべません。","english":"I don't eat meat."}],"level":"N5"},{"id":33,"expression":"ました","meaning":"polite past verb","category":"Verb Forms","format":"Verb ます-stem + ました","usages":[{"usage":"Report a completed action","japanese":"昨日(きのう)映画(えいが)を見(み)ました。","reading":"きのう えいがを みました。","english":"I watched a movie yesterday."}],"level":"N5"},{"id":34,"expression":"ませんでした","meaning":"polite past negative","category":"Verb Forms","format":"Verb ます-stem + ませんでした","usages":[{"usage":"Say an action did not happen","japanese":"昨日(きのう)勉強(べんきょう)しませんでした。","reading":"きのう べんきょうしませんでした。","english":"I did not study yesterday."}],"level":"N5"},{"id":35,"expression":"辞書形","meaning":"dictionary form","category":"Verb Forms","format":"Verb dictionary form (う / る ending)","usages":[{"usage":"Use the plain nonpast form","japanese":"毎日(まいにち)日本語(にほんご)を勉強(べんきょう)する。","reading":"まいにち にほんごを べんきょうする。","english":"I study Japanese every day."}],"level":"N5"},{"id":36,"expression":"ない形","meaning":"plain negative form","category":"Verb Forms","format":"Verb ない-form","usages":[{"usage":"Make a casual negative","japanese":"今日(きょう)は行(い)かない。","reading":"きょうは いかない。","english":"I'm not going today."}],"level":"N5"},{"id":37,"expression":"た形","meaning":"plain past form","category":"Verb Forms","format":"Verb た-form","usages":[{"usage":"Report a past event casually","japanese":"昨日(きのう)寿司(すし)を食(た)べた。","reading":"きのう すしを たべた。","english":"I ate sushi yesterday."}],"level":"N5"},{"id":38,"expression":"て形","meaning":"connecting form","category":"Verb Forms","format":"Verb て-form","usages":[{"usage":"Connect sequential actions","japanese":"朝(あさ)ご飯(はん)を食(た)べて、出(で)かけます。","reading":"あさごはんを たべて、でかけます。","english":"I eat breakfast and go out."}],"level":"N5"},{"id":39,"expression":"てください","meaning":"please do","category":"Requests","format":"Verb て-form + ください","usages":[{"usage":"Make a polite request","japanese":"名前(なまえ)を書(か)いてください。","reading":"なまえを かいてください。","english":"Please write your name."}],"level":"N5"},{"id":40,"expression":"ないでください","meaning":"please do not","category":"Requests","format":"Verb ない-form + でください","usages":[{"usage":"Politely prohibit an action","japanese":"ここで写真(しゃしん)を撮(と)らないでください。","reading":"ここで しゃしんを とらないでください。","english":"Please don't take pictures here."}],"level":"N5"},{"id":41,"expression":"てもいいです","meaning":"may / allowed to","category":"Requests","format":"Verb て-form + もいいです","usages":[{"usage":"Ask or give permission","japanese":"窓(まど)を開(あ)けてもいいですか。","reading":"まどを あけてもいいですか。","english":"May I open the window?"}],"level":"N5"},{"id":42,"expression":"てはいけません","meaning":"must not","category":"Requests","format":"Verb て-form + はいけません","usages":[{"usage":"State a prohibition","japanese":"ここで泳(およ)いではいけません。","reading":"ここで およいではいけません。","english":"You must not swim here."}],"level":"N5"},{"id":43,"expression":"ています","meaning":"ongoing action or state","category":"Verb Forms","format":"Verb て-form + います","usages":[{"usage":"Describe an ongoing action","japanese":"今(いま)本(ほん)を読(よ)んでいます。","reading":"いま ほんを よんでいます。","english":"I am reading a book now."},{"usage":"Describe a resulting state","japanese":"結婚(けっこん)しています。","reading":"けっこんしています。","english":"I am married."}],"level":"N5"},{"id":44,"expression":"ましょう","meaning":"let's","category":"Invitations","format":"Verb ます-stem + ましょう","usages":[{"usage":"Suggest doing something together","japanese":"一緒(いっしょ)に帰(かえ)りましょう。","reading":"いっしょに かえりましょう。","english":"Let's go home together."}],"level":"N5"},{"id":45,"expression":"ませんか","meaning":"would you like to","category":"Invitations","format":"Verb ます-stem + ませんか","usages":[{"usage":"Invite someone politely","japanese":"週末(しゅうまつ)映画(えいが)を見(み)ませんか。","reading":"しゅうまつ えいがを みませんか。","english":"Would you like to watch a movie this weekend?"}],"level":"N5"},{"id":46,"expression":"たいです","meaning":"want to do","category":"Desires","format":"Verb ます-stem + たいです","usages":[{"usage":"Express your wish to do something","japanese":"日本(にほん)へ行(い)きたいです。","reading":"にほんへ いきたいです。","english":"I want to go to Japan."}],"level":"N5"},{"id":47,"expression":"たくないです","meaning":"do not want to do","category":"Desires","format":"Verb ます-stem + たくないです","usages":[{"usage":"Express an unwanted action","japanese":"今日(きょう)は外(そと)に出(で)たくないです。","reading":"きょうは そとに でたくないです。","english":"I don't want to go outside today."}],"level":"N5"},{"id":48,"expression":"がほしいです","meaning":"want a thing","category":"Desires","format":"Noun + がほしいです","usages":[{"usage":"Express desire for an object","japanese":"新(あたら)しい自転車(じてんしゃ)がほしいです。","reading":"あたらしい じてんしゃが ほしいです。","english":"I want a new bicycle."}],"level":"N5"},{"id":49,"expression":"に行きます","meaning":"go to do","category":"Purpose","format":"Verb ます-stem + に + 行きます / 来ます","usages":[{"usage":"Express the purpose of movement","japanese":"昼(ひる)ご飯(はん)を食(た)べに行(い)きます。","reading":"ひるごはんを たべに いきます。","english":"I'm going to eat lunch."}],"level":"N5"},{"id":50,"expression":"ことができます","meaning":"can do","category":"Ability","format":"Verb dictionary form + ことができます","usages":[{"usage":"Describe an ability","japanese":"日本語(にほんご)を話(はな)すことができます。","reading":"にほんごを はなすことが できます。","english":"I can speak Japanese."}],"level":"N5"},{"id":51,"expression":"のが好きです","meaning":"like doing","category":"Likes","format":"Verb dictionary form + のが好きです","usages":[{"usage":"Express enjoyment of an activity","japanese":"泳(およ)ぐのが好(す)きです。","reading":"およぐのが すきです。","english":"I like swimming."}],"level":"N5"},{"id":52,"expression":"前に","meaning":"before","category":"Time","format":"Verb dictionary form / Noun + の + 前に","usages":[{"usage":"Place an action before another","japanese":"寝(ね)る前(まえ)に歯(は)を磨(みが)きます。","reading":"ねるまえに はを みがきます。","english":"I brush my teeth before sleeping."}],"level":"N5"},{"id":53,"expression":"後で","meaning":"after","category":"Time","format":"Verb た-form / Noun + の + 後で","usages":[{"usage":"Place an action after another","japanese":"仕事(しごと)の後(あと)で走(はし)ります。","reading":"しごとの あとで はしります。","english":"I run after work."}],"level":"N5"},{"id":54,"expression":"時","meaning":"when / at the time","category":"Time","format":"Verb / adjective / Noun + の + 時","usages":[{"usage":"Describe when something happens","japanese":"暇(ひま)な時(とき)、本(ほん)を読(よ)みます。","reading":"ひまな とき、ほんを よみます。","english":"When I'm free, I read books."}],"level":"N5"},{"id":55,"expression":"から〜まで","meaning":"from ... to","category":"Time","format":"Starting point + から + endpoint + まで","usages":[{"usage":"Specify a time range","japanese":"九時(くじ)から六時(ろくじ)まで働(はたら)きます。","reading":"くじから ろくじまで はたらきます。","english":"I work from nine to six."}],"level":"N5"},{"id":56,"expression":"ぐらい・くらい","meaning":"about / approximately","category":"Quantities","format":"Number / duration + ぐらい / くらい","usages":[{"usage":"Estimate a quantity","japanese":"駅(えき)まで十分(じゅっぷん)ぐらいです。","reading":"えきまで じゅっぷんぐらいです。","english":"It's about ten minutes to the station."}],"level":"N5"},{"id":57,"expression":"だけ","meaning":"only","category":"Quantities","format":"Noun / number + だけ","usages":[{"usage":"Restrict the amount","japanese":"一(ひと)つだけください。","reading":"ひとつだけ ください。","english":"Just one, please."}],"level":"N5"},{"id":58,"expression":"もう","meaning":"already / another","category":"Time","format":"もう + past verb; もう + quantity","usages":[{"usage":"Ask whether something is done","japanese":"もう宿題(しゅくだい)をしましたか。","reading":"もう しゅくだいを しましたか。","english":"Have you done your homework already?"},{"usage":"Request one more","japanese":"もう一杯(いっぱい)ください。","reading":"もう いっぱい ください。","english":"One more cup, please."}],"level":"N5"},{"id":59,"expression":"まだ","meaning":"not yet / still","category":"Time","format":"まだ + negative verb; まだ + state","usages":[{"usage":"State something is not finished","japanese":"まだ食(た)べていません。","reading":"まだ たべていません。","english":"I haven't eaten yet."},{"usage":"State something continues","japanese":"まだ雨(あめ)が降(ふ)っています。","reading":"まだ あめが ふっています。","english":"It's still raining."}],"level":"N5"},{"id":60,"expression":"あまり〜ない","meaning":"not very","category":"Quantities","format":"あまり + negative predicate","usages":[{"usage":"Express a low degree","japanese":"この映画(えいが)はあまり面白(おもしろ)くないです。","reading":"この えいがは あまり おもしろくないです。","english":"This movie isn't very interesting."}],"level":"N5"},{"id":61,"expression":"全然〜ない","meaning":"not at all","category":"Quantities","format":"全然 + negative predicate","usages":[{"usage":"Strongly negate something","japanese":"全然(ぜんぜん)分(わ)かりません。","reading":"ぜんぜん わかりません。","english":"I don't understand at all."}],"level":"N5"},{"id":62,"expression":"とても","meaning":"very","category":"Quantities","format":"とても + adjective / adverb","usages":[{"usage":"Intensify a description","japanese":"この料理(りょうり)はとても美味(おい)しいです。","reading":"このりょうりは とても おいしいです。","english":"This dish is very delicious."}],"level":"N5"},{"id":63,"level":"N4","expression":"V-ようとする","meaning":"Be about to A; Try to A","format":"Verb volitional form (意向形) + とする","category":"Verb Forms & Conjugation","usages":[{"usage":"Be about to A; Try to A","japanese":"ジェーンはまさに家から出ようとしていた。","reading":"ジェーンはまさにいえからでようとしていた。","english":"Jane was about to leave the house."}]},{"id":64,"level":"N4","expression":"V-ようと思う","meaning":"I think I will A","format":"Verb volitional form (意向形) + と思う","category":"Verb Forms & Conjugation","usages":[{"usage":"I think I will A","japanese":"外国に行こうと思っている。","reading":"がいこくにいこうとおもっている。","english":"I'm thinking I'll go abroad."}]},{"id":65,"level":"N4","expression":"〜ちゃ、〜じゃ","meaning":"ちゃ is a casual form of ては","format":"Verb て-form + は → ちゃ / Verb で-form + は → じゃ; Verb なくては → なくちゃ","category":"Other Expressions","usages":[{"usage":"ちゃ is a casual form of ては","japanese":"試験勉強をしなくちゃ。","reading":"しけんべんきょうをしなくちゃ。","english":"I have to prepare for the test."},{"usage":"じゃ is a casual form of では","japanese":"いや、それじゃだめだ。逆になるように回してごらん。","reading":"いや、それじゃだめだ。ぎゃくになるようにまわしてごらん。","english":"No, that's not the right way. You have to turn it the other way round."}]},{"id":66,"level":"N4","expression":"あげる","meaning":"Give B to A (A is a third party, not yourself)","format":"Giver + は + recipient + に + object + を + あげる","category":"Other Expressions","usages":[{"usage":"Give B to A (A is a third party, not yourself)","japanese":"あなたは、だれでも欲しい人にこの写真をあげてもいい。","reading":"あなたは、だれでもほしいひとにこのしゃしんをあげてもいい。","english":"You may give this picture to whoever wants it."}]},{"id":67,"level":"N4","expression":"いただく","meaning":"A receives C from B: the giver is of a higher rank than the recipient.","format":"Humble: (speaker) が + (person) に + Noun を + いただく (いただけますか)","category":"Polite & Honorific","usages":[{"usage":"A receives C from B: the giver is of a higher rank than the recipient.","japanese":"お水をいただけますか。","reading":"おみずをいただけますか。","english":"Could I get some water, please?"}]},{"id":68,"level":"N4","expression":"Humble verbs","meaning":"Humble form of A","format":"お + Verb ます-stem + する / ご + Sino-Japanese する-noun + する; special humble verbs (伺う・参る・申す etc.)","category":"Other Expressions","usages":[{"usage":"Humble form of A","japanese":"旦那のカードをお借りしてバッグを買った。","reading":"だんなのカードをおかりしてバッグをかった。","english":"I borrowed my husband's credit card and bought a bag."},{"usage":"Humble form of する verbs","japanese":"図書室なら私がご案内しましょう。","reading":"としょしつならわたしがごあんないしましょう。","english":"As to the library I'll show you (there)."}]},{"id":69,"level":"N4","expression":"終わる","meaning":"To finish A; A ends","format":"Verb ます-stem + 終わる","category":"Other Expressions","usages":[{"usage":"To finish A; A ends","japanese":"朝ご飯を食べおわったあとでお風呂に入りました。","reading":"あさごはんをたべおわったあとでおふろにはいりました。","english":"I took a bath after I finished eating breakfast."}]},{"id":70,"level":"N4","expression":"か","meaning":"A is a question within the sentence","format":"Plain-form clause + か + Verb (聞く・分かる etc.); interrogative + か; Noun + か + Noun; sentence + か","category":"Questions & Expressions","usages":[{"usage":"A is a question within the sentence","japanese":"このパーティーはいつなのか、友達に聞いてみよう。","reading":"このパーティーはいつなのか、ともだちにきいてみよう。","english":"Let's try asking a friend when this party is."},{"usage":"Some A; Any A (somebody, somewhere, sometime, somehow, etc.)","japanese":"だれかが私を呼んでいるようだ。","reading":"だれかがわたしをよんでいるようだ。","english":"It seems like someone is calling me."},{"usage":"Forms the question form of the sentence A","japanese":"おばあさんはお元気ですか。","reading":"おばあさんはおげんきですか。","english":"Is Grandma doing well?"},{"usage":"A or B","japanese":"私は京都か大阪に旅行に行きたい。","reading":"わたしはきょうとかおおさかにりょこうにいきたい。","english":"I want to travel to Kyoto or Osaka."}]},{"id":71,"level":"N4","expression":"かい","meaning":"Follows A; turning the sentence into a yes/no question (casual).","format":"Plain-form sentence + かい (casual question)","category":"Questions & Expressions","usages":[{"usage":"Follows A; turning the sentence into a yes/no question (casual).","japanese":"本当にできるのかい？","reading":"ほんとうにできるのかい？","english":"Can you handle it?"}]},{"id":72,"level":"N4","expression":"かしら","meaning":"I wonder A ?","format":"Plain-form sentence + かしら (I wonder)","category":"Other Expressions","usages":[{"usage":"I wonder A ?","japanese":"今日は暑くなるかしら？","reading":"きょうはあつくなるかしら？","english":"I wonder if today will get hot?"}]},{"id":73,"level":"N4","expression":"方","meaning":"How to A; Way/style of A","format":"Verb ます-stem + 方 (かた)","category":"Other Expressions","usages":[{"usage":"How to A; Way/style of A","japanese":"日本の漫画の読みかたは右から左だ。","reading":"にほんのまんがのよみかたはみぎからひだりだ。","english":"The way to read a Japanese comic is from right to left."}]},{"id":74,"level":"N4","expression":"かどうか","meaning":"Whether or not A","format":"Plain-form clause / Noun + かどうか + Verb","category":"Other Expressions","usages":[{"usage":"Whether or not A","japanese":"あの子供は顔を見ても、男かどうか全然分からない。","reading":"あのこどもはかおをみても、おとこかどうかぜんぜんわからない。","english":"Even if I look at that child's face, I don't know if the child is a boy or not."}]},{"id":75,"level":"N4","expression":"かもしれない","meaning":"Might A; maybe A; perhaps A","format":"Plain-form clause / Noun・な-adjective + かもしれない","category":"Verb Forms & Conjugation","usages":[{"usage":"Might A; maybe A; perhaps A","japanese":"それは本当かもしれない。","reading":"それはほんとうかもしれない。","english":"It may be true."}]},{"id":76,"level":"N4","expression":"がする","meaning":"Hear A; smell A; taste A","format":"Noun (sound / smell / taste / feeling) + がする","category":"Contrast & Conditions","usages":[{"usage":"Hear A; smell A; taste A","japanese":"そのピアノはよい音がする。","reading":"そのピアノはよいおとがする。","english":"The piano has a good tone."}]},{"id":77,"level":"N4","expression":"がっている","meaning":"Wants to A","format":"Verb ます-stem + たがっている; い-adj (-い) / な-adj + がっている","category":"Verb Forms & Conjugation","usages":[{"usage":"Wants to A","japanese":"ずっとパパの車に乗りたがってたのよね。今日は幼稚園まで車で送ってってよ。","reading":"ずっとパパのくるまにのりたがってたのよね。きょうはようちえんまでくるまでおくってってよ。","english":"She's always wanted to ride in Daddy (your)'s car. She asked for you to take her to kindergarten today."},{"usage":"Shows signs of state/condition A","japanese":"あやちゃんは何かを欲しがっている。","reading":"あやちゃんはなにかをほしがっている。","english":"It seems like Aya wants something."},{"usage":"Don't be A (afraid, shy, etc.)","japanese":"そんなに恥ずかしがらないで堂々とスピーチしてください。","reading":"そんなにはずかしがらないでどうどうとスピーチしてください。","english":"Don't be so shy and please give a great speech."}]},{"id":78,"level":"N4","expression":"下さる","meaning":"Give B to A (A is you, your friends, your family, etc.)","format":"Respectful giver + が + recipient + に + item + を + くださる","category":"Other Expressions","usages":[{"usage":"Give B to A (A is you, your friends, your family, etc.)","japanese":"校長先生はお土産を下さいました。","reading":"こうちょうせんせいはおみやげをくださいました。","english":"The principal gave me a souvenir."}]},{"id":79,"level":"N4","expression":"くれる","meaning":"A gives C to B (B is you, your friends, your family, etc.)","format":"Person + が + (me/my in-group) に + item + を + くれる","category":"Verb Forms & Conjugation","usages":[{"usage":"A gives C to B (B is you, your friends, your family, etc.)","japanese":"お願いだ！僕にチャンスをくれ。","reading":"おねがいだ！ぼくにチャンスをくれ。","english":"Come on! Give me a chance."}]},{"id":80,"level":"N4","expression":"ことがある","meaning":"There are times when A (occurs/exists)","format":"Verb dictionary form + ことがある (occasionally); contrast with Verb た-form + ことがある (past experience)","category":"Contrast & Conditions","usages":[{"usage":"There are times when A (occurs/exists)","japanese":"その二人は仲がとてもよいが、大喧嘩をすることがある。","reading":"そのふたりはなかがとてもよいが、おおげんかをすることがある。","english":"Those two get along very well, but there are times when they have big fights."}]},{"id":81,"level":"N4","expression":"ことができる","meaning":"Be able to A; can do A","format":"Verb dictionary form + ことができる","category":"Contrast & Conditions","usages":[{"usage":"Be able to A; can do A","japanese":"あなたのおかげで、私は早く終えることができました。","reading":"あなたのおかげで、わたしははやくおえることができました。","english":"Thanks to your help, I was able to finish early."},{"usage":"Can A; be possible to A (possibility of the subject to do A)","japanese":"「乗り放題」という切符を買ったら、何回でも電車にのることができる。","reading":"「のりほうだい」というきっぷをかったら、なんかいでもでんしゃにのることができる。","english":"If you buy an all-you-can-ride ticket, it's possible to ride the train as many times as you like."}]},{"id":82,"level":"N4","expression":"ことにする","meaning":"Decide to A","format":"Verb dictionary form / ない-form + ことにする; ～ことにしている (habit)","category":"Verb Forms & Conjugation","usages":[{"usage":"Decide to A","japanese":"あの人はあまり好きじゃないので話さないことにする。","reading":"あのひとはあまりすきじゃないのではなさないことにする。","english":"I'm not going to talk to that person because I don't like him."},{"usage":"To make a rule/habit of A","japanese":"私は６時に起きることにしている。","reading":"わたしは６じにおきることにしている。","english":"I make it a rule to get up at six."}]},{"id":83,"level":"N4","expression":"ことになる","meaning":"To be decided that A; A is decided (by someone else)","format":"Verb dictionary form / ない-form + ことになる; clause + ことになる (logical conclusion)","category":"Verb Forms & Conjugation","usages":[{"usage":"To be decided that A; A is decided (by someone else)","japanese":"昨日の会議で、パーティーが２１日に行われることになりました。","reading":"きのうのかいぎで、パーティーが２１にちにおこなわれることになりました。","english":"It was decided at the meeting yesterday to have the party on the 21st."},{"usage":"Shows a natural/logical conclusion A","japanese":"後十分歩いたら、今日は一時間運動したことになる。","reading":"あとじゅっぷんあるいたら、きょうはいちじかんうんどうしたことになる。","english":"If you walk ten more minutes, you will have exercised an hour today."}]},{"id":84,"level":"N4","expression":"ござる／ございます","meaning":"ござる is the polite form of ある.","format":"ございます (polite あります); Noun + でございます (polite です)","category":"Other Expressions","usages":[{"usage":"ござる is the polite form of ある.","japanese":"お荷物はいくつございますか。","reading":"おにもつはいくつございますか。","english":"How much baggage do you have?"}]},{"id":85,"level":"N4","expression":"さ","meaning":"Changes A into a noun","format":"い-adjective (-い) + さ / な-adjective stem + さ → noun (height, length, etc.)","category":"Other Expressions","usages":[{"usage":"Changes A into a noun","japanese":"それの高さはいくらですか。","reading":"それのたかさはいくらですか。","english":"What is the height of that?"}]},{"id":86,"level":"N4","expression":"差し上げる","meaning":"Give B to A (A is a third party, not yourself)","format":"Humble giver + が + respected recipient + に + item + を + 差し上げる","category":"Polite & Honorific","usages":[{"usage":"Give B to A (A is a third party, not yourself)","japanese":"飲み物を差し上げましょうか。","reading":"のみものをさしあげましょうか。","english":"May I offer you a drink?"}]},{"id":87,"level":"N4","expression":"Causative Passive","meaning":"Be made to do A","format":"Verb causative-passive form: Group 1 -aせられる / -aされる; Group 2 -させられる; する→させられる; 来る→来させられる","category":"Other Expressions","usages":[{"usage":"Be made to do A","japanese":"給食の時、生徒は先生に野菜を全部食べさせられました。","reading":"きゅうしょくのとき、せいとはせんせいにやさいをぜんぶたべさせられました。","english":"During school lunch, the students were forced by the teacher to eat all of the vegetables."}]},{"id":88,"level":"N4","expression":"Causative","meaning":"Make (somebody) A, this is coercive or forced onto the object of the sentence.","format":"Verb causative form: Group 1 -aせる; Group 2 -させる; する→させる; 来る→来させる","category":"Other Expressions","usages":[{"usage":"Make (somebody) A, this is coercive or forced onto the object of the sentence.","japanese":"お母さん、いや！私は先週やったので、今度はお兄さんに片付けさせて。","reading":"おかあさん、いや！わたしはせんしゅうやったので、こんどはおにいさんにかたづけさせて。","english":"No, mom! I did it last week, so make (my) brother clean up this time."},{"usage":"Allow (somebody) to A, this is permission from the subject to the object.","japanese":"息子はあの映画をすごく見たがっているけど、よくないので見させません。","reading":"むすこはあのえいがをすごくみたがっているけど、よくないのでみさせません。","english":"My son really wants to watch that movie, but it's not any good so I won't let him watch it."},{"usage":"Make (somebody) A, because of the subject; the object is caused to A","japanese":"だいきは一週間家に帰らなかったので、両親をとても心配させました。","reading":"だいきはいっしゅうかんいえにかえらなかったので、りょうしんをとてもしんぱいさせました。","english":"Daiki hasn't come back home in a week, so his parents are really worried."}]},{"id":89,"level":"N4","expression":"し(〜し)","meaning":"A and ... (used to list reasons, with each reason followed by し)","format":"Plain-form clause + し、(clause + し) + conclusion","category":"Other Expressions","usages":[{"usage":"A and ... (used to list reasons, with each reason followed by し)","japanese":"早いし、安いし、うまい！それはどこの牛丼ですか？","reading":"はやいし、やすいし、うまい！それはどこのぎゅうどんですか？","english":"It was made quickly and is cheap and yummy. Where is this gyudon from?"}]},{"id":90,"level":"N4","expression":"しまう","meaning":"To finish/complete A","format":"Verb て-form + しまう (completion / regret); Verb dictionary form しまう = put away","category":"Other Expressions","usages":[{"usage":"To finish/complete A","japanese":"作文は書いてしまいましたか。","reading":"さくぶんはかいてしまいましたか。","english":"Have you finished writing your composition?"},{"usage":"A occurs (shows embarrassment / regret / disappointment over the action A)","japanese":"２日後に食べ物が無くなってしまった。","reading":"ふつかごにたべものがなくなってしまった。","english":"After two days our food ran out."},{"usage":"To put away A","japanese":"財布をしまって置きなさい。","reading":"さいふをしまっておきなさい。","english":"Put away your wallet."}]},{"id":91,"level":"N4","expression":"すぎる","meaning":"A is done too much","format":"Verb ます-stem + すぎる; い-adj (-い) + すぎる; な-adj stem + すぎる","category":"Other Expressions","usages":[{"usage":"A is done too much","japanese":"昨日は食べすぎてお腹が痛くなりました。","reading":"きのうはたべすぎておなかがいたくなりました。","english":"Yesterday I ate too much so my stomach hurt."},{"usage":"Too much A; A is excessive","japanese":"このカレーは辛すぎて食べられない！","reading":"このカレーはからすぎてたべられない！","english":"This curry is too spicy; I can't eat it!"}]},{"id":92,"level":"N4","expression":"ずに","meaning":"Without A..ing","format":"Verb ない-form (-ない) + ずに (する→せずに)","category":"Verb Forms & Conjugation","usages":[{"usage":"Without A..ing","japanese":"ノックをせずに私の部屋に入ってくるな。","reading":"ノックをせずにわたしのへやにはいってくるな。","english":"Don't come into my room without knocking."}]},{"id":93,"level":"N4","expression":"そう","meaning":"A is spoken by/heard from someone/something else","format":"Plain-form clause + そうだ (hearsay); Verb ます-stem / い-adj (-い) / な-adj stem + そうだ (appearance)","category":"Appearance & Possibility","usages":[{"usage":"A is spoken by/heard from someone/something else","japanese":"聞いた？レッドソックスは昨日勝ったそうだ！","reading":"きいた？レッドソックスはきのうかったそうだ！","english":"Did you hear? (I heard) The Red Sox won yesterday!"},{"usage":"It looks A; it seems like A","japanese":"外は雨が降りそうだから傘を持っていってね。","reading":"そとはあめがふりそうだからかさをもっていってね。","english":"It looks like it will rain outside, so take an umbrella."}]},{"id":94,"level":"N4","expression":"それに","meaning":"A. Furthermore, B","format":"Sentence A。それに、sentence B。","category":"Particles & Connectors","usages":[{"usage":"A. Furthermore, B","japanese":"片付けは苦手。それに全部大事な物なの。","reading":"かたづけはにがて。それにぜんぶだいじなものなの。","english":"I'm not good at tidying up. Besides, these are all important things."}]},{"id":95,"level":"N4","expression":"たことがある","meaning":"Have done A before","format":"Verb た-form + ことがある","category":"Contrast & Conditions","usages":[{"usage":"Have done A before","japanese":"あなたはここに来る前に雪を見たことがありましたか。","reading":"あなたはここにくるまえにゆきをみたことがありましたか。","english":"Have you ever seen snow before you came here?"}]},{"id":96,"level":"N4","expression":"例えば","meaning":"For example, A","format":"Noun / phrase + 例えば + example; 例えば、...など","category":"Other Expressions","usages":[{"usage":"For example, A","japanese":"キャンプに必要な物、例えば寝袋を忘れないこと。","reading":"キャンプにひつようなもの、たとえばねぶくろをわすれないこと。","english":"We can't forget the necessary things for camping, for example, sleeping bags."}]},{"id":97,"level":"N4","expression":"ため(に)","meaning":"Because of A; due to A","format":"Plain-form clause / Noun + の + ため(に) (cause / purpose); Verb dictionary form + ために (purpose)","category":"Reasons & Causes","usages":[{"usage":"Because of A; due to A","japanese":"休校は雪のためであった。","reading":"きゅうこうはゆきのためであった。","english":"The closing of school was due to the snow."},{"usage":"For the purpose/sake of A; in order to A","japanese":"あなたを愛するために私は生まれた。","reading":"あなたをあいするためにわたしはうまれた。","english":"I was born to love you."}]},{"id":98,"level":"N4","expression":"たら","meaning":"If A","format":"Verb / い-adj past (-かった) / な-adj・Noun + だった + ら、B","category":"Verb Forms & Conjugation","usages":[{"usage":"If A","japanese":"私だったら、ご飯だけおごってもらって、後はさっさと帰るよ。","reading":"わたしだったら、ごはんだけおごってもらって、あとはさっさとかえるよ。","english":"If it was me, I would accept just the meal then hurry on home afterwards."},{"usage":"When A; after A (then B)","japanese":"家に着いたら君に電話するよ。","reading":"いえについたらきみにでんわするよ。","english":"I will give you a call after I get home."},{"usage":"When A, then B","japanese":"シャワーを浴びたら、気分がすっきりした。","reading":"シャワーをあびたら、きぶんがすっきりした。","english":"I felt refreshed after showering."},{"usage":"How about A; why don't you A","japanese":"その仕事に応募したらどうだい。","reading":"そのしごとにおうぼしたらどうだい。","english":"Why don't you apply for that job?"}]},{"id":99,"level":"N4","expression":"た方がいい","meaning":"It would be better to A","format":"Verb た-form + 方がいい; Verb ない-form + 方がいい","category":"Contrast & Conditions","usages":[{"usage":"It would be better to A","japanese":"もう一度考えた方がいいです。","reading":"もういちどかんがえたほうがいいです。","english":"It would be better to think it over."}]},{"id":100,"level":"N4","expression":"だい","meaning":"Turns sentence A into a question (casual).","format":"Plain-form sentence + だい (male-coded casual)","category":"Questions & Expressions","usages":[{"usage":"Turns sentence A into a question (casual).","japanese":"なぜ君は僕に冷たいんだい？","reading":"なぜきみはぼくにつめたいんだい？","english":"Why are you cold with me ?"},{"usage":"Used by young males to make an assertion (ending in A)","japanese":"僕だったら大丈夫だい。","reading":"ぼくだったらだいじょうぶだい。","english":"I'd be fine if it was me."}]},{"id":101,"level":"N4","expression":"出す","meaning":"A (suddenly) begins","format":"Verb ます-stem + 出す (start suddenly); Verb ます-stem + 出す (outwards)","category":"Other Expressions","usages":[{"usage":"A (suddenly) begins","japanese":"昨日授業の後に雨が降りだしました。","reading":"きのうじゅぎょうのあとにあめがふりだしました。","english":"Yesterday it started to rain after class finished."},{"usage":"To A out","japanese":"この計算方法は先生が導き出したんだよ。","reading":"このけいさんほうほうはせんせいがみちびきだしたんだよ。","english":"This calculation method was deduced by the teacher."}]},{"id":102,"level":"N4","expression":"だろう","meaning":"Probably A; I think A; it seems A; I wonder A","format":"Plain-form clause + だろう; Noun・な-adj + だろう","category":"Appearance & Possibility","usages":[{"usage":"Probably A; I think A; it seems A; I wonder A","japanese":"彼は多分失敗するだろう。","reading":"かれはたぶんしっぱいするだろう。","english":"He probably will fail, right?"}]},{"id":103,"level":"N4","expression":"だろうと思う","meaning":"I think probably A","format":"Plain-form clause + だろうと思う","category":"Appearance & Possibility","usages":[{"usage":"I think probably A","japanese":"明日は雨が降るだろうと思う。","reading":"あしたはあめがふるだろうとおもう。","english":"I am afraid it will rain tomorrow."}]},{"id":104,"level":"N4","expression":"続ける","meaning":"A continues; To continue to A","format":"Verb ます-stem + 続ける","category":"Other Expressions","usages":[{"usage":"A continues; To continue to A","japanese":"そのように勉強しつづけたらすぐに上手になるでしょう？","reading":"そのようにべんきょうしつづけたらすぐにじょうずになるでしょう？","english":"If you continue to study like that, soon you'll get really good, right?"}]},{"id":105,"level":"N4","expression":"つもりだ","meaning":"Plan to A; be going to A; intend to do A","format":"Verb dictionary form / ない-form + つもりだ; Noun + のつもり","category":"Verb Forms & Conjugation","usages":[{"usage":"Plan to A; be going to A; intend to do A","japanese":"何をするつもりですか？変なことは止めてください！","reading":"なにをするつもりですか？へんなことはやめてください！","english":"What are you going to do? Please don't do anything weird!"},{"usage":"Supposed to be A; intended to be A; assumed to be A","japanese":"これはほんの冗談のつもりだった。","reading":"これはほんのじょうだんのつもりだった。","english":"It was meant as merely a joke."},{"usage":"Intending to A","japanese":"私は東京で一人暮らしをするつもりで、お金を貯めてきた。","reading":"わたしはとうきょうでひとりぐらしをするつもりで、おかねをためてきた。","english":"Intending to live on my own in Tokyo, I saved my money."}]},{"id":106,"level":"N4","expression":"てあげる","meaning":"Do B for someone","format":"Verb て-form + あげる","category":"Verb Forms & Conjugation","usages":[{"usage":"Do B for someone","japanese":"ダイエット？じゃ、僕が君の分を代わりに食べてあげる。","reading":"ダイエット？じゃ、ぼくがきみのぶんをかわりにたべてあげる。","english":"You are on a diet? Then I'll eat your portion for you!"}]},{"id":107,"level":"N4","expression":"ていく","meaning":"To get to A","format":"Verb て-form + いく (movement away / progression into future)","category":"Verb Forms & Conjugation","usages":[{"usage":"To get to A","japanese":"手術が終わったので、これから痛みが消えていくよ。","reading":"しゅじゅつがおわったので、これからいたみがきえていくよ。","english":"The surgery is finished, so the pain will begin to disappear."},{"usage":"To go on A..ing","japanese":"今日からしっかり練習していけば、本番には完璧な演奏ができるよ。","reading":"きょうからしっかりれんしゅうしていけば、ほんばんにはかんぺきなえんそうができるよ。","english":"If we practice steadily from today on, we will have a flawless performance in front of an audience."}]},{"id":108,"level":"N4","expression":"ていただく","meaning":"B does C for A","format":"Verb て-form + いただく (humbly receive a favor)","category":"Verb Forms & Conjugation","usages":[{"usage":"B does C for A","japanese":"あなたの机を使わせていただけますか。","reading":"あなたのつくえをつかわせていただけますか。","english":"Could I use (would you let me use) your desk?"}]},{"id":109,"level":"N4","expression":"て頂けないでしょうか?","meaning":"Could you please A for me?","format":"Verb て-form + いただけないでしょうか (very polite request)","category":"Verb Forms & Conjugation","usages":[{"usage":"Could you please A for me?","japanese":"１０００円札を崩していただけませんか。","reading":"１０００えんさつをくずしていただけませんか。","english":"Could you change a ¥1,000 note?"}]},{"id":110,"level":"N4","expression":"て置く","meaning":"To do A in advance; do A as preparation for something else","format":"Verb て-form + おく (prepare / leave as is)","category":"Verb Forms & Conjugation","usages":[{"usage":"To do A in advance; do A as preparation for something else","japanese":"あなたの名前と住所を書き留めて置きましょう。","reading":"あなたのなまえとじゅうしょをかきとめておきましょう。","english":"I will write down your name and address."},{"usage":"To leave as is in the state A","japanese":"ドアを開けて置かないで。","reading":"ドアをあけておかないで。","english":"Don't leave the door open."}]},{"id":111,"level":"N4","expression":"て下さる","meaning":"A does C for B (B is you, your friends, your family, etc.)","format":"Verb て-form + くださる (respectful favor to speaker)","category":"Verb Forms & Conjugation","usages":[{"usage":"A does C for B (B is you, your friends, your family, etc.)","japanese":"女王様が私を思いっきり踏みつけて下さいました。","reading":"じょおうさまがわたしをおもいっきりふみつけてくださいました。","english":"I really let the Queen walk all over me."}]},{"id":112,"level":"N4","expression":"てくる","meaning":"To come to A","format":"Verb て-form + くる (movement toward / progression until now)","category":"Verb Forms & Conjugation","usages":[{"usage":"To come to A","japanese":"学校で習う漢字は前よりむずかしくなってきている。","reading":"がっこうでならうかんじはまえよりむずかしくなってきている。","english":"The kanji I learn at school have gotten more difficult than before."},{"usage":"To continue A..ing; to have become A","japanese":"この花は祖母が種から育ててきたひまわりです。","reading":"このはなはそぼがたねからそだててきたひまわりです。","english":"This flower is a sunflower that my grandmother grew from a seed."}]},{"id":113,"level":"N4","expression":"てくれてありがとう","meaning":"Thank you for doing A","format":"Verb て-form + くれてありがとう","category":"Verb Forms & Conjugation","usages":[{"usage":"Thank you for doing A","japanese":"今日は私の誕生日パーティーに来てくれてありがとう。","reading":"きょうはわたしのたんじょうびパーティーにきてくれてありがとう。","english":"Thank you for coming to my birthday party today."}]},{"id":114,"level":"N4","expression":"てくれる","meaning":"A does B for C (C is you, your friends, your family, etc.)","format":"Verb て-form + くれる","category":"Verb Forms & Conjugation","usages":[{"usage":"A does B for C (C is you, your friends, your family, etc.)","japanese":"先生なのに私の質問に答えてくれなかった。","reading":"せんせいなのにわたしのしつもんにこたえてくれなかった。","english":"Even though she is the teacher, she didn't answer my question."}]},{"id":115,"level":"N4","expression":"て差し上げる","meaning":"Do B for someone (above you)","format":"Verb て-form + 差し上げる (humble giving of favor)","category":"Verb Forms & Conjugation","usages":[{"usage":"Do B for someone (above you)","japanese":"もしよかったら、手伝って差し上げませんか？","reading":"もしよかったら、てつだってさしあげませんか？","english":"If it's all right, can I help you?"}]},{"id":116,"level":"N4","expression":"てはいけない","meaning":"May not A; must not A","format":"Verb て-form + はいけない","category":"Verb Forms & Conjugation","usages":[{"usage":"May not A; must not A","japanese":"お父さんに逆らってはいけない。","reading":"おとうさんにさからってはいけない。","english":"Don't go against your father."},{"usage":"In order to avoid A; A would be bad, and so…","japanese":"その花瓶は落とすといけないから、私が持ちますね。","reading":"そのかびんはおとすといけないから、わたしがもちますね。","english":"It would be bad to drop that vase, so I'll carry it (e.g. instead of you)."}]},{"id":117,"level":"N4","expression":"て欲しい","meaning":"I want (person, thing) A to B (action)","format":"Verb て-form + ほしい (speaker wants another person to do it)","category":"Verb Forms & Conjugation","usages":[{"usage":"I want (person, thing) A to B (action)","japanese":"この書類を今すぐ彼女に届けて欲しい。","reading":"このしょるいをいますぐかのじょにとどけてほしい。","english":"I want you to take this paper to her right away."},{"usage":"Want A to not B","japanese":"この部屋でタバコを吸わないで欲しいです。","reading":"このへやでタバコをすわないでほしいです。","english":"I don't want you to smoke in this room."},{"usage":"Would love for A to (not) happen","japanese":"身だしなみにはいつも気をつけて欲しいものだ。","reading":"みだしなみにはいつもきをつけてほしいものだ。","english":"I would really like for you to always pay attention to your personal appearance."}]},{"id":118,"level":"N4","expression":"てみる","meaning":"Try to A","format":"Verb て-form + みる (try doing)","category":"Verb Forms & Conjugation","usages":[{"usage":"Try to A","japanese":"あのシャツを着てみなさい。","reading":"あのシャツをきてみなさい。","english":"Try on that shirt."}]},{"id":119,"level":"N4","expression":"ても、〜でも","meaning":"Even if A","format":"Verb て-form + も / Verb で-form + も (even if)","category":"Verb Forms & Conjugation","usages":[{"usage":"Even if A","japanese":"たとえ土砂降りでも行かなければならない。","reading":"たとえどしゃぶりでもいかなければならない。","english":"I have to go even if it rains cats and dogs."}]},{"id":120,"level":"N4","expression":"てもいい","meaning":"It is alright to A; the subject may A; it's alright if A (condition)","format":"Verb て-form + もいい","category":"Verb Forms & Conjugation","usages":[{"usage":"It is alright to A; the subject may A; it's alright if A (condition)","japanese":"そう心配しなくてもいいよ。","reading":"そうしんぱいしなくてもいいよ。","english":"You don't have to worry so much."}]},{"id":121,"level":"N4","expression":"てもかまわない","meaning":"It doesn't matter if A is done","format":"Verb て-form + もかまわない","category":"Verb Forms & Conjugation","usages":[{"usage":"It doesn't matter if A is done","japanese":"ステレオを掛けてもかまわないかい。","reading":"ステレオをかけてもかまわないかい。","english":"Mind if I play the stereo?"},{"usage":"Doesn't matter if A (isn't done); don't mind if A (isn't done)","japanese":"彼が賛成しなくても構わない。","reading":"かれがさんせいしなくてもかまわない。","english":"It doesn't matter whether he agrees or not."}]},{"id":122,"level":"N4","expression":"てもらう","meaning":"B does C for A","format":"Verb て-form + もらう","category":"Verb Forms & Conjugation","usages":[{"usage":"B does C for A","japanese":"あなたに宿題を手伝ってもらいたかった。","reading":"あなたにしゅくだいをてつだってもらいたかった。","english":"I wanted you to help me with my homework."}]},{"id":123,"level":"N4","expression":"てやる","meaning":"Do B for someone (below you)","format":"Verb て-form + やる (favor, casual/downward)","category":"Verb Forms & Conjugation","usages":[{"usage":"Do B for someone (below you)","japanese":"いいことを教えてやる。","reading":"いいことをおしえてやる。","english":"I'll tell you something good. (e.g. a secret)"}]},{"id":124,"level":"N4","expression":"でござる／でございます","meaning":"でござる is the polite form of である.","format":"Noun / な-adjective stem + でございます","category":"Other Expressions","usages":[{"usage":"でござる is the polite form of である.","japanese":"交換台でございます。","reading":"こうかんだいでございます。","english":"This is the operator."}]},{"id":125,"level":"N4","expression":"でも","meaning":"Any A (anywhere, anybody, anytime, etc.)","format":"Noun / interrogative + でも; sentence A。でも、sentence B。","category":"Particles & Connectors","usages":[{"usage":"Any A (anywhere, anybody, anytime, etc.)","japanese":"いつでもそれを使ってください。","reading":"いつでもそれをつかってください。","english":"You may use it any time."},{"usage":"Even A","japanese":"子供にでもそれはできる。","reading":"こどもにでもそれはできる。","english":"Even a child can do it."},{"usage":"A or something","japanese":"あれ？何だろ？パフォーマンスでもやってるのか？","reading":"あれ？なんだろ？パフォーマンスでもやってるのか？","english":"Eh, what's that? Somebody doing street theatre or something?"},{"usage":"Even if I have to A, by all means A","japanese":"何としてでも夏までに痩せたい。","reading":"なんとしてでもなつまでにやせたい。","english":"No matter what it takes, I want to lose weight by the summer."}]},{"id":126,"level":"N4","expression":"と","meaning":"When/if A, then B","format":"Verb dictionary form / ない-form + と、B (natural result / condition); Noun + と + Noun (and)","category":"Particles & Connectors","usages":[{"usage":"When/if A, then B","japanese":"このキノコ、食べると笑いが止まらなくなるんだって。","reading":"このキノコ、たべるとわらいがやまらなくなるんだって。","english":"They say that if you eat this mushroom, you won't be able to stop laughing."},{"usage":"A and B (and C,etc..)","japanese":"このパンと、こっちのケーキ、どちらも食べたいです。","reading":"このパンと、こっちのケーキ、どちらもたべたいです。","english":"I want to eat both this bread and this cake."},{"usage":"With A; to A","japanese":"私は彼と映画に行きました。","reading":"わたしはかれとえいがにいきました。","english":"I went to a movie with him."},{"usage":"Shows a sequence of two events A and B","japanese":"少し走ると息が切れた。","reading":"すこしはしるといきがきれた。","english":"I ran a bit and I ran out of breath."},{"usage":"When/if A (polite/formal version)","japanese":"私は明日ですと、一日中空いています。","reading":"わたしはあしたですと、いちにちじゅうあいています。","english":"If it's tomorrow, I'm open (available) all day."}]},{"id":127,"level":"N4","expression":"と (思う、言う、考える)","meaning":"That A","format":"Plain-form quotation + と + 思う / 言う / 考える","category":"Other Expressions","usages":[{"usage":"That A","japanese":"私は彼を親友の一人だと考えています。","reading":"わたしはかれをしんゆうのひとりだとかんがえています。","english":"I think of him as one of my good friends."}]},{"id":128,"level":"N4","expression":"とと、どちらが〜","meaning":"Which is more C; A or B","format":"Noun A + と + Noun B + と、どちらが + adjective? (comparison)","category":"Contrast & Conditions","usages":[{"usage":"Which is more C; A or B","japanese":"これとあれとでは、どちらが安いのですか。","reading":"これとあれとでは、どちらがやすいのですか。","english":"Which is cheaper, this or that?"}]},{"id":129,"level":"N4","expression":"という","meaning":"B is called A","format":"Noun + という + Noun; clause + という + Noun","category":"Particles & Connectors","usages":[{"usage":"B is called A","japanese":"「桜」という曲、聞いたことあるの？","reading":"「さくら」というきょく、きいたことあるの？","english":"Have you ever heard the song called \"Sakura\"?"},{"usage":"All A; every A; this (very) A","japanese":"この時期の家という家はクリスマスの飾りで輝いている。","reading":"このじきのいえといういえはクリスマスのかざりでかがやいている。","english":"In this season, every house shines with Christmas decorations."},{"usage":"A is information about B","japanese":"近所に新しいパン屋さんができるという話を聞いた？","reading":"きんじょにあたらしいパンやさんができるというはなしをきいた？","english":"Did you hear the talk about the new bakery opening in the neighborhood?"},{"usage":"It's said that A (hearsay, rumor, report, or legend)","japanese":"昔この池に河童がいたという。","reading":"むかしこのいけにかっぱがいたという。","english":"It's said that there was a kappa (mythical creature) in this pond long ago."}]},{"id":130,"level":"N4","expression":"ということ","meaning":"Changes sentence/phrase A into a noun","format":"Plain-form clause + ということ","category":"Particles & Connectors","usages":[{"usage":"Changes sentence/phrase A into a noun","japanese":"運転するということは得意ね。","reading":"うんてんするということはとくいね。","english":"He's good at driving, isn't he?"},{"usage":"Presents information A; A is heard (and repeated in this sentence)","japanese":"噂によれば、今年のクラブに入る１年生の人数は大変多いということです。","reading":"うわさによれば、ことしのクラブにはいる１ねんせいのにんずうはたいへんおおいということです。","english":"According to the rumors, it looks like that there are a lot of first year students joining clubs this year."}]},{"id":131,"level":"N4","expression":"とか〜とか","meaning":"A, B, etc.","format":"Noun / Verb dictionary form + とか + Noun / Verb dictionary form + とか","category":"Particles & Connectors","usages":[{"usage":"A, B, etc.","japanese":"パチンコとか競馬とか、そんなデートはいやよ！","reading":"パチンコとかけいばとか、そんなデートはいやよ！","english":"I don't want a date with stuff like pachinko or horse racing!"}]},{"id":132,"level":"N4","expression":"ところ","meaning":"About to A","format":"Verb dictionary form + ところ (about to); Verb ている + ところ (in progress); Verb た + ところ (just finished)","category":"Particles & Connectors","usages":[{"usage":"About to A","japanese":"しおりさんが発表するところだからよく聞きなさい。","reading":"しおりさんがはっぴょうするところだからよくききなさい。","english":"Shiori is about to present, so listen well."},{"usage":"Be now A...ing (be in the middle of doing A)","japanese":"私たちが訪ねた時、彼は兄さんに英語を教えてもらっているところであった。","reading":"わたしたちがたずねたとき、かれはあにさんにえいごをおしえてもらっているところであった。","english":"He was being taught English by his brother when we called on him."},{"usage":"Just finished A; Have been A...ing","japanese":"あなたのボーイフレンドは待ちくたびれて、今帰ったところよ。","reading":"あなたのボーイフレンドはまちくたびれて、いまかえったところよ。","english":"Your boyfriend got tired of waiting for you and left just now."},{"usage":"After A is done, the results of A are B","japanese":"日本の番組をみたところ、すごい事件が起きてるらしい。","reading":"にほんのばんぐみをみたところ、すごいじけんがおきてるらしい。","english":"Judging from the program from Japan, it seems like a major incident is happening."}]},{"id":133,"level":"N4","expression":"どうしても","meaning":"No matter what, A; by any means necessary A","format":"どうしても + verb / negative / adjective","category":"Verb Forms & Conjugation","usages":[{"usage":"No matter what, A; by any means necessary A","japanese":"それはどうしても我慢できない。","reading":"それはどうしてもがまんできない。","english":"I can not stomach it."}]},{"id":134,"level":"N4","expression":"ない方がいい","meaning":"It would be better to not A","format":"Verb ない-form + 方がいい","category":"Verb Forms & Conjugation","usages":[{"usage":"It would be better to not A","japanese":"彼女は今怒っているので話さない方がいい。","reading":"かのじょはいまおこっているのではなさないほうがいい。","english":"She's angry right now, so it's better to not speak to her."}]},{"id":135,"level":"N4","expression":"なくてはいけない","meaning":"Must do A; have to A","format":"Verb ない-form (-ない) + なくてはいけない","category":"Verb Forms & Conjugation","usages":[{"usage":"Must do A; have to A","japanese":"だけど、明日はお客さんとも会わなくちゃいけないし。","reading":"だけど、あしたはおきゃくさんともあわなくちゃいけないし。","english":"But I have an appointment with my client tomorrow."}]},{"id":136,"level":"N4","expression":"なくてもいい","meaning":"Don't have to A","format":"Verb ない-form (-ない) + なくてもいい","category":"Verb Forms & Conjugation","usages":[{"usage":"Don't have to A","japanese":"そんなに緊張しなくてもいいですよ。","reading":"そんなにきんちょうしなくてもいいですよ。","english":"There's no need to be that tense."}]},{"id":137,"level":"N4","expression":"なければならない","meaning":"Must do A; have to A","format":"Verb ない-form (-ない) + なければならない","category":"Verb Forms & Conjugation","usages":[{"usage":"Must do A; have to A","japanese":"明日試験があるから徹夜で勉強しなければならない","reading":"あしたしけんがあるからてつやでべんきょうしなければならない","english":"There's a test tomorrow, so I need to stay up all night and study."}]},{"id":138,"level":"N4","expression":"なさい","meaning":"Do A (instruction)","format":"Verb ます-stem + なさい","category":"Other Expressions","usages":[{"usage":"Do A (instruction)","japanese":"出かける前に部屋の掃除をしなさい。","reading":"でかけるまえにへやのそうじをしなさい。","english":"Please clean your room before you head out."}]},{"id":139,"level":"N4","expression":"など,なんて,なんか","meaning":"Marks the end of the non-exhaustive list A","format":"Noun + など / なんて / なんか; clause + なんて","category":"Verb Forms & Conjugation","usages":[{"usage":"Marks the end of the non-exhaustive list A","japanese":"この店は食料品、例えばバター、チーズ、砂糖などを売っている。","reading":"このみせはしょくりょうひん、たとえばバター、チーズ、さとうなどをうっている。","english":"The store sells foodstuffs, such as butter, cheese, and sugar."},{"usage":"Things like A; for example A","japanese":"こんな料理など、食べたくないわ。","reading":"こんなりょうりなど、たべたくないわ。","english":"I don't want to eat something like this."},{"usage":"Used to emphasize negative B","japanese":"こんな服なんかいやだよ。","reading":"こんなふくなんかいやだよ。","english":"I don't like clothes like this."},{"usage":"What (did) A","japanese":"今なんて言ったの？","reading":"いまなんていったの？","english":"What did you just say?"},{"usage":"What is the name of A","japanese":"この花はなんていう名前ですか？","reading":"このはなはなんていうなまえですか？","english":"What's the name of this flower?"},{"usage":"How A; What A","japanese":"なんて美しい景色でしょう。","reading":"なんてうつくしいけしきでしょう。","english":"What beautiful scenery."},{"usage":"Shows a strong emotion or feeling about A","japanese":"彼に限って裏切りなどあるものか。","reading":"かれにかぎってうらぎりなどあるものか。","english":"There's just no way he could betray me."}]},{"id":140,"level":"N4","expression":"なら","meaning":"If A is the case/situation","format":"Noun / な-adjective stem + なら; Verb / い-adjective plain form + なら","category":"Other Expressions","usages":[{"usage":"If A is the case/situation","japanese":"アメリカへ行くつもりなら、英語をしっかりとやり直しなさい。","reading":"アメリカへいくつもりなら、えいごをしっかりとやりなおしなさい。","english":"If you are intending to go to America, brush up your English."},{"usage":"As for A","japanese":"彼ならいつでも力になってくれるよ。","reading":"かれならいつでもちからになってくれるよ。","english":"He'll always come through."}]},{"id":141,"level":"N4","expression":"に","meaning":"In A; on A; at A","format":"Noun + に; Verb ます-stem + に + 行く / 来る (purpose)","category":"Particles & Connectors","usages":[{"usage":"In A; on A; at A","japanese":"私の部屋に可愛い猫がいます。","reading":"わたしのへやにかわいいねこがいます。","english":"There is a cute cat in my room."},{"usage":"To A; towards A; on A","japanese":"大阪に行きたい。","reading":"おおさかにいきたい。","english":"I wanna go to Osaka."},{"usage":"At A (time)","japanese":"六時に起きます。","reading":"ろくじにおきます。","english":"I wake up at 6 o'clock."},{"usage":"Used with passive verbs to identify who/what is doing the action","japanese":"咲子はよく先生に呼ばれて、しかられていた。","reading":"さきこはよくせんせいによばれて、しかられていた。","english":"Sakiko was often called and scolded by the teacher."},{"usage":"To change into A","japanese":"新しい職場は、山奥の病院になった。","reading":"あたらしいしょくばは、やまおくのびょういんになった。","english":"My new workplace will be (was decided to be) a hospital deep in the mountains."},{"usage":"Every period of time A, B; Per A, B","japanese":"月に一回、海へ行くんです。","reading":"つきにいっかい、うみへいくんです。","english":"I go to the beach once a month."},{"usage":"A and B","japanese":"このセットはコーヒーにケーキが付きます。","reading":"このセットはコーヒーにケーキがつきます。","english":"In this set, the coffee comes with cake."},{"usage":"Going/coming/returning to do A","japanese":"夏は北海道に遊びに行きたい。","reading":"なつはほっかいどうにあそびにいきたい。","english":"In the summer, I want to go to Hokkaido to have fun."},{"usage":"Shows the target/recipient A of the action","japanese":"彼は彼女に朝食を作った。","reading":"かれはかのじょにちょうしょくをつくった。","english":"He made breakfast for her."}]},{"id":142,"level":"N4","expression":"にくい","meaning":"A is hard/difficult to do","format":"Verb ます-stem + にくい","category":"Particles & Connectors","usages":[{"usage":"A is hard/difficult to do","japanese":"あなたの質問は答えにくい。","reading":"あなたのしつもんはこたえにくい。","english":"Your question is hard to answer."}]},{"id":143,"level":"N4","expression":"に帰る","meaning":"Return (home) in order to A","format":"Verb ます-stem + に + 帰る (purpose of returning)","category":"Particles & Connectors","usages":[{"usage":"Return (home) in order to A","japanese":"冬休み中、実家へ家族に会いに帰る大学生は多い。","reading":"ふゆやすみちゅう、じっかへかぞくにあいにかえるだいがくせいはおおい。","english":"There are a lot of college students who return home during winter holiday to see their families."},{"usage":"Return to A","japanese":"７時までに家に帰らなくてはならない。","reading":"７じまでにいえにかえらなくてはならない。","english":"I have to be back home by seven."}]},{"id":144,"level":"N4","expression":"にくる","meaning":"Come (here) in order to A","format":"Verb ます-stem + に + 来る","category":"Particles & Connectors","usages":[{"usage":"Come (here) in order to A","japanese":"君は手伝いに来てくれたの？ありがとう、助かりました！","reading":"きみはてつだいにきてくれたの？ありがとう、たすかりました！","english":"You came to help me? Thanks a lot!"}]},{"id":145,"level":"N4","expression":"にいく","meaning":"Go (somewhere) in order to A","format":"Verb ます-stem + に + 行く","category":"Particles & Connectors","usages":[{"usage":"Go (somewhere) in order to A","japanese":"私の町は店がほとんどないのでよく東京へ買い物をしに行きます。","reading":"わたしのまちはみせがほとんどないのでよくとうきょうへかいものをしにいきます。","english":"There are hardly any stores in my town, so I often go to Tokyo to shop."}]},{"id":146,"level":"N4","expression":"の","meaning":"Follows A; turning the sentence into a question (casual).","format":"Plain-form clause + の (nominalization / explanation); Noun A + の + Noun B (possession)","category":"Questions & Expressions","usages":[{"usage":"Follows A; turning the sentence into a question (casual).","japanese":"綾子にはその話をきちんと伝えたの？","reading":"あやこにはそのはなしをきちんとつたえたの？","english":"Did you accurately tell Ayako about that discussion?"},{"usage":"A's B (shows possession); the A B","japanese":"彼女のパソコンは古い。","reading":"かのじょのパソコンはふるい。","english":"Her computer is old."},{"usage":"The A one","japanese":"新しい靴は安いのを買うつもりです。","reading":"あたらしいくつはやすいのをかうつもりです。","english":"For my new shoes, I plan on buying inexpensive ones."},{"usage":"A directly modifies B, B of A","japanese":"彼からのメールが久しぶりに届いた。","reading":"かれからのメールがひさしぶりにとどいた。","english":"I got the first email from him in awhile."},{"usage":"B who/that is a(n) A","japanese":"総理大臣の佐藤さんは近所に住んでいる。","reading":"そうりだいじんのさとうさんはきんじょにすんでいる。","english":"The Prime Minister Sato lives nearby."},{"usage":"C which/whose A is B. C's A is B","japanese":"あの髪の長い人は私の妹です。","reading":"あのかみのながいひとはわたしのいもうとです。","english":"That person with the long hair is my younger sister."}]},{"id":147,"level":"N4","expression":"の、〜こと","meaning":"Changes A into a noun","format":"Verb plain form + の / こと + particle (nominalization)","category":"Particles & Connectors","usages":[{"usage":"Changes A into a noun","japanese":"妹の歌を聞くのは楽しかった。","reading":"いもうとのうたをきくのはたのしかった。","english":"It was fun listening to my little sister's song."}]},{"id":148,"level":"N4","expression":"ので","meaning":"Because A; since A","format":"Verb / い-adjective plain form + ので; Noun / な-adj + なので","category":"Reasons & Causes","usages":[{"usage":"Because A; since A","japanese":"父は母と会話をしたくないので、休日はいつもゴルフしに行きます。","reading":"ちちはははとかいわをしたくないので、きゅうじつはいつもゴルフしにいきます。","english":"My dad always goes to play golf on his days off because he doesn't want to speak to my mother."}]},{"id":149,"level":"N4","expression":"のに","meaning":"Even though A; in spite of A","format":"Verb / い-adjective plain form + のに; Noun / な-adj + なのに","category":"Contrast & Conditions","usages":[{"usage":"Even though A; in spite of A","japanese":"婚約しているのにキスを拒否された。","reading":"こんやくしているのにキスをきょひされた。","english":"Even though we're engaged she wouldn't let me kiss her."},{"usage":"In order to A; in the process of doing A","japanese":"私は兄たちが遊びに行くのにいつもくっついていった。","reading":"わたしはあにたちがあそびにいくのにいつもくっついていった。","english":"I always went along with my older brothers to play."}]},{"id":150,"level":"N4","expression":"の上では","meaning":"From the standpoint of A; according to A; as far as A is concerned","format":"Noun + の上では (on the surface of / in terms of)","category":"Particles & Connectors","usages":[{"usage":"From the standpoint of A; according to A; as far as A is concerned","japanese":"仕事の上では、彼は全く問題がない。","reading":"しごとのうえでは、かれはまったくもんだいがない。","english":"He's not a problem at all at work."}]},{"id":151,"level":"N4","expression":"始める","meaning":"To begin to A; A begins","format":"Verb ます-stem + 始める","category":"Other Expressions","usages":[{"usage":"To begin to A; A begins","japanese":"晩ご飯を食べた後、テレビを見はじめました。","reading":"ばんごはんをたべたあと、テレビをみはじめました。","english":"After I ate dinner I began to watch TV."}]},{"id":152,"level":"N4","expression":"はず","meaning":"It should be A; it ought to be A","format":"Verb / い-adjective plain form + はずだ; Noun + のはず; な-adj + なはず","category":"Particles & Connectors","usages":[{"usage":"It should be A; it ought to be A","japanese":"彼女は宿題を終えてしまったはずだ。","reading":"かのじょはしゅくだいをおえてしまったはずだ。","english":"She ought to have finished her homework."}]},{"id":153,"level":"N4","expression":"はずがない","meaning":"Cannot be A; should not be A (when describing a situation, not the actions of the subject)","format":"Verb / い-adjective plain form + はずがない; Noun + のはずがない","category":"Verb Forms & Conjugation","usages":[{"usage":"Cannot be A; should not be A (when describing a situation, not the actions of the subject)","japanese":"彼はそれを見たはずがない。","reading":"かれはそれをみたはずがない。","english":"He cannot have seen it."}]},{"id":154,"level":"N4","expression":"ばかり","meaning":"Do only A; do nothing but A","format":"Noun / number + ばかり; Verb た-form + ばかり (just did)","category":"Limits & Degree","usages":[{"usage":"Do only A; do nothing but A","japanese":"ゆうこちゃんは笑ってばかりだね。泣いたところを一回も見たことがない。","reading":"ゆうこちゃんはわらってばかりだね。ないたところをいっかいもみたことがない。","english":"Yuuko is always smiling. I haven't seen her crying a single time."},{"usage":"A just finished/ended/occured.","japanese":"私は、テニスを始めたばかりです。","reading":"わたしは、テニスをはじめたばかりです。","english":"I've just started playing tennis."},{"usage":"Shows a continual/continuing negative change A","japanese":"このままでは生活が苦しくなっていくばかりだ。","reading":"このままではせいかつがくるしくなっていくばかりだ。","english":"As it is, our way of living will keep getting difficult."},{"usage":"Around/about A; Approximately A","japanese":"毎日の通勤で往復2時間ばかりかかっています。","reading":"まいにちのつうきんでおうふく2じかんばかりかかっています。","english":"It takes around two hours going to and from work each day."}]},{"id":155,"level":"N4","expression":"ほど","meaning":"So much B that it's like A","format":"Plain-form clause / quantity + ほど","category":"Limits & Degree","usages":[{"usage":"So much B that it's like A","japanese":"島国に住んでいるほどシーフードを食べる。","reading":"しまぐににすんでいるほどシーフードをたべる。","english":"They eat so much seafood that it's like they're an islander."},{"usage":"There is nothing as B as A.","japanese":"あの青い鳥ほど高く飛べる動物はいない。","reading":"あのあおいとりほどたかくとべるどうぶつはいない。","english":"There is not an animal that can fly as high as that blue bird."},{"usage":"The more A, B","japanese":"私は彼のことを思うほど幸せになります。","reading":"わたしはかれのことをおもうほどしあわせになります。","english":"The more I think of him the happier I get."},{"usage":"About A; around A (approximation)","japanese":"このズボンの丈を３センチほど長くしてください。","reading":"このズボンのたけを３センチほどながくしてください。","english":"Please make these pants about 3 centimeters longer."}]},{"id":156,"level":"N4","expression":"ほど〜ない","meaning":"A is not as C as B","format":"Noun A + は + Noun B + ほど + adjective negative","category":"Verb Forms & Conjugation","usages":[{"usage":"A is not as C as B","japanese":"月は太陽ほど明るくない。","reading":"つきはたいようほどあかるくない。","english":"The moon is not as bright as the sun."}]},{"id":157,"level":"N4","expression":"まで","meaning":"Until A; up to A; as far as A","format":"Time / place + まで","category":"Time & Sequence","usages":[{"usage":"Until A; up to A; as far as A","japanese":"水が腰まで来た。","reading":"みずがこしまできた。","english":"The water came up to my waist."},{"usage":"Even A","japanese":"彼はスポーツまで得意なんです。","reading":"かれはスポーツまでとくいなんです。","english":"He's even good at sports."}]},{"id":158,"level":"N4","expression":"までに","meaning":"By A; by the time A","format":"Time / deadline + までに","category":"Time & Sequence","usages":[{"usage":"By A; by the time A","japanese":"いつまでに必要ですか。","reading":"いつまでにひつようですか。","english":"By when do you need it?"}]},{"id":159,"level":"N4","expression":"まま","meaning":"The situation A remains unchanged","format":"Verb た-form / ない-form + まま; Noun + のまま; な-adj + なまま","category":"Other Expressions","usages":[{"usage":"The situation A remains unchanged","japanese":"あなたはそのことを言わないままにして置く方が良い。","reading":"あなたはそのことをいわないままにしておくほうがよい。","english":"It would be better if that remains unsaid."}]},{"id":160,"level":"N4","expression":"もらう","meaning":"A receives C from B: the giver is of the same/lower rank of the recipient.","format":"Receiver + は + giver + に / から + object + を + もらう","category":"Particles & Connectors","usages":[{"usage":"A receives C from B: the giver is of the same/lower rank of the recipient.","japanese":"ばあちゃんの形見に、入れ歯をもらった。","reading":"ばあちゃんのかたみに、はいれはをもらった。","english":"I got some false teeth that were left by my grandmother as a memento."}]},{"id":161,"level":"N4","expression":"やすい","meaning":"A is easy to do","format":"Verb ます-stem + やすい","category":"Other Expressions","usages":[{"usage":"A is easy to do","japanese":"日本人はいつでも、箸の方がたべやすいです。","reading":"にほんじんはいつでも、はしのほうがたべやすいです。","english":"For Japanese people, it's always easier to use chopsticks when they eat."}]},{"id":162,"level":"N4","expression":"やる","meaning":"Give B to A (A is an animal, plant, or someone below you in ranking)","format":"Giver + が + recipient + に + object + を + やる","category":"Other Expressions","usages":[{"usage":"Give B to A (A is an animal, plant, or someone below you in ranking)","japanese":"今日と明日は畑に肥料をやらなきゃなぁ。","reading":"きょうとあしたははたけにひりょうをやらなきゃなぁ。","english":"Today and tomorrow I have to fertilize the field."}]},{"id":163,"level":"N4","expression":"ようだ","meaning":"It seems/looks like A","format":"Verb / い-adj plain + ようだ; Noun + のようだ; な-adj + なようだ","category":"Verb Forms & Conjugation","usages":[{"usage":"It seems/looks like A","japanese":"彼は少し疲れているようだ。","reading":"かれはすこしつかれているようだ。","english":"He looks a bit tired."},{"usage":"As A; Like A","japanese":"田中さんは機械のように速く、正確に、宛名シールを貼りました。","reading":"たなかさんはきかいのようにはやく、せいかくに、あてなシールをはりました。","english":"Ms. Tanaka applied the address stickers like a machine, quickly and accurately."}]},{"id":164,"level":"N4","expression":"ようにする","meaning":"Try to A; make sure to A","format":"Verb dictionary form / ない-form + ようにする","category":"Verb Forms & Conjugation","usages":[{"usage":"Try to A; make sure to A","japanese":"ねぇ、なるべく早く帰るようにするから、ご飯食べないで待っててよ。","reading":"ねぇ、なるべくはやくかえるようにするから、ごはんたべないでまっててよ。","english":"Hey, I'm going to try and get home as soon as possible, so don't eat and wait for me."}]},{"id":165,"level":"N4","expression":"ようになる／なくなる","meaning":"Come to A (transition over time)","format":"Verb dictionary form / ない-form + ようになる; potential verb + ようになる","category":"Verb Forms & Conjugation","usages":[{"usage":"Come to A (transition over time)","japanese":"漢字が上手に書けるようになって、うれしかった。","reading":"かんじがじょうずにかけるようになって、うれしかった。","english":"I was delighted to have learned how to write kanji skillfully."},{"usage":"Come to be unable to A, come to no longer be A","japanese":"君には時々我慢できなくなる。","reading":"きみにはときどきがまんできなくなる。","english":"Sometimes I can't stand you."}]},{"id":166,"level":"N4","expression":"ように言う","meaning":"Tell someone to do A","format":"Verb dictionary form / ない-form + ように + 言う","category":"Verb Forms & Conjugation","usages":[{"usage":"Tell someone to do A","japanese":"医者は彼に酒の量を減らすように言った。","reading":"いしゃはかれにさけのりょうをへらすようにいった。","english":"His doctor told him to cut down on drinking."}]},{"id":167,"level":"N4","expression":"より","meaning":"A is C-er than B; A is more C than B (comparison).","format":"A + より + B (comparison)","category":"Other Expressions","usages":[{"usage":"A is C-er than B; A is more C than B (comparison).","japanese":"ピカチューはあなたより頭がいいみたいだなぁ。","reading":"ピカチューはあなたよりあたまがいいみたいだなぁ。","english":"It seems like Pikachu is smarter than you."},{"usage":"A is not as C as B","japanese":"あっちのラーメン屋はこの店より高くないよ。","reading":"あっちのラーメンやはこのみせよりたかくないよ。","english":"That ramen place is not more expensive than this place."}]},{"id":168,"level":"N4","expression":"より〜の方が〜","meaning":"B is more C than A","format":"Noun A + より + Noun B + の方が + adjective","category":"Contrast & Conditions","usages":[{"usage":"B is more C than A","japanese":"この自転車よりもそのバイクの方がかっこいい！","reading":"このじてんしゃよりもそのバイクのほうがかっこいい！","english":"That motorbike is cooler than this bicycle."},{"usage":"A is more C than B","japanese":"奥さんの方が私より怖いと思います。","reading":"おくさんのほうがわたしよりこわいとおもいます。","english":"I think my wife is scarier than I am."}]},{"id":169,"level":"N4","expression":"らしい","meaning":"I heard that A; it seems like A; it appears that A","format":"Plain-form clause + らしい (hearsay); Noun + らしい (typical of)","category":"Appearance & Possibility","usages":[{"usage":"I heard that A; it seems like A; it appears that A","japanese":"彼は大変眠いらしい。","reading":"かれはたいへんねむいらしい。","english":"He seems to be very sleepy."},{"usage":"Just like A; typical of A","japanese":"自分のことを考える前に人のことを考えるのはまさに彼女らしい。","reading":"じぶんのことをかんがえるまえにひとのことをかんがえるのはまさにかのじょらしい。","english":"It is just like her to think of others before thinking of herself."}]},{"id":170,"level":"N4","expression":"Potential","meaning":"Can A; be able to A (ability of the subject)","format":"Verb potential form: Group 1 -eる; Group 2 -られる (colloquial -れる); する→できる; 来る→来られる","category":"Other Expressions","usages":[{"usage":"Can A; be able to A (ability of the subject)","japanese":"この謎は解けない！もう、諦める！","reading":"このなぞはとけない！もう、あきらめる！","english":"I can't solve this riddle. I give up!"},{"usage":"Can A; be possible to A; (possibility of the subject to do A)","japanese":"そのボタンを押したらロボットを動かせるよ。","reading":"そのボタンをおしたらロボットをうごかせるよ。","english":"If you push this button, you can make the robot move."}]},{"id":171,"level":"N4","expression":"んです","meaning":"The reason/explanation is A","format":"Plain-form clause + んです; Noun / な-adj + なんです","category":"Particles & Connectors","usages":[{"usage":"The reason/explanation is A","japanese":"君の気持ちは受け取りました。でも私結婚してるんです。","reading":"きみのきもちはうけとりました。でもわたしけっこんしてるんです。","english":"I've gotten (understand) your feelings, but I'm married."},{"usage":"Do / don’t do A","japanese":"いいかげん甘えてるんじゃないよ。","reading":"いいかげんあまえてるんじゃないよ。","english":"Don't behave like a careless, spoiled child."}]},{"id":172,"level":"N4","expression":"んですが","meaning":"Introduces a request, invitation, or asking for permission","format":"Plain-form clause + んですが; Noun / な-adj + なんですが","category":"Contrast & Conditions","usages":[{"usage":"Introduces a request, invitation, or asking for permission","japanese":"この自動販売機、動かないんですが。","reading":"このじどうはんばいき、うごかないんですが。","english":"This vending machine isn't working."}]},{"id":173,"level":"N4","expression":"中／中","meaning":"Throughout A; all over A; during the course of A","format":"Verb ている + 中 / Noun + 中 (ちゅう) (during); Noun + 中 (じゅう) (throughout)","category":"Other Expressions","usages":[{"usage":"Throughout A; all over A; during the course of A","japanese":"今学期中に、本を100冊読みたいです。","reading":"こんがっきじゅうに、ほんを100さつよみたいです。","english":"I want to read a hundred books this semester."},{"usage":"During A (period of time); in the middle of A","japanese":"6月中の日本は雨ばかり降っています。","reading":"6がつちゅうのにほんはあめばかりふっています。","english":"It does nothing but rain in Japan throughout June."},{"usage":"Action A is currently ongoing/in the middle of","japanese":"今週中に宿題をしてきてください。","reading":"こんしゅうじゅうにしゅくだいをしてきてください。","english":"Please do the homework during this week."}]},{"id":174,"level":"N4","expression":"Passive","meaning":"Be A-ed (Passive tense), when the action is directed at the subject.","format":"Verb passive form: Group 1 -aれる; Group 2 -られる; する→される; 来る→来られる","category":"Other Expressions","usages":[{"usage":"Be A-ed (Passive tense), when the action is directed at the subject.","japanese":"この車は十年前に作られました。","reading":"このくるまはじゅうねんまえにつくられました。","english":"This car was made ten years ago."},{"usage":"A is done, A happens","japanese":"外で遊んでいる最中、雨に降られた！","reading":"そとであそんでいるさいちゅう、あめにふられた！","english":"While I was playing outside it started to rain!"},{"usage":"A does B","japanese":"彼が運転されました。","reading":"かれがうんてんされました。","english":"He drove."}]},{"id":175,"level":"N4","expression":"合う","meaning":"To do A together/mutually","format":"Verb ます-stem + 合う (mutually)","category":"Other Expressions","usages":[{"usage":"To do A together/mutually","japanese":"アランと私はしばらくの間お互いに見つめ合った。","reading":"アランとわたしはしばらくのあいだおたがいにみつめあった。","english":"Alan and I looked at one another for a while."}]},{"id":176,"level":"N4","expression":"Imperative","meaning":"Do A (command)","format":"Verb imperative form: Group 1 -e; Group 2 -ろ / -よ; する→しろ; 来る→来い","category":"Other Expressions","usages":[{"usage":"Do A (command)","japanese":"早く食え！そして、さっさと学校に行け！","reading":"はやくくえ！そして、さっさとがっこうにいけ！","english":"Hurry up, eat, then quickly head off to school!"}]},{"id":177,"level":"N4","expression":"Respectful verbs","meaning":"Respectful form of A","format":"Special respectful verbs (いらっしゃる・おっしゃる etc.); お + Verb ます-stem + になる / ご + Sino-Japanese noun + になる","category":"Other Expressions","usages":[{"usage":"Respectful form of A","japanese":"さあ、お召し上がりください。","reading":"さあ、おめしあがりください。","english":"Alright, please eat!"}]},{"id":178,"level":"N4","expression":"必要","meaning":"It is not necessary for A to be done.","format":"Noun + が + 必要だ / 必要です; Verb dictionary form + 必要がある","category":"Other Expressions","usages":[{"usage":"It is not necessary for A to be done.","japanese":"夏休みだから学校へ行く必要はないんだ。","reading":"なつやすみだからがっこうへいくひつようはないんだ。","english":"It's summer vacation so there's no need to go to school."},{"usage":"There is a need to A; A is necessary","japanese":"私たちは環境問題について考える必要がある。","reading":"わたしたちはかんきょうもんだいについてかんがえるひつようがある。","english":"It's necessary for us to think about environmental issues."},{"usage":"A is necessary","japanese":"この車は修理の必要があります。","reading":"このくるまはしゅうりのひつようがあります。","english":"This car needs repairing."}]},{"id":179,"level":"N4","expression":"Volitional","meaning":"Let's A","format":"Verb volitional form: Group 1 -oう; Group 2 -よう; する→しよう; 来る→来よう","category":"Other Expressions","usages":[{"usage":"Let's A","japanese":"お母さんは五年前に「いつか旅行に行こう」といったのに、まだどこにも行ってない！","reading":"おかあさんはごねんまえに「いつかりょこうにいこう」といったのに、まだどこにもいってない！","english":"Even though Mom said \"Let's go on a vacation,\" 5 years ago, we still haven't gone anywhere!"}]},{"id":180,"level":"N4","expression":"Conditional Form","meaning":"If A","format":"Verb conditional ば-form: Group 1 -eば; Group 2 -れば; い-adj (-い) + ければ; する→すれば","category":"Other Expressions","usages":[{"usage":"If A","japanese":"外国人が日本で運転したければ国際免許が必要だ。","reading":"がいこくじんがにほんでうんてんしたければこくさいめんきょがひつようだ。","english":"If foreigners want to drive in Japan, an international driver's license is needed."}]},{"id":181,"level":"N4","expression":"Prohibitive","meaning":"Don't A","format":"Verb dictionary form + な (prohibitive)","category":"Other Expressions","usages":[{"usage":"Don't A","japanese":"ここでは走るな。","reading":"ここでははしるな。","english":"Don't run here."}]},{"id":182,"level":"N4","expression":"が聞こえる","meaning":"Can be heard; is audible","format":"Sound / voice / music + が聞こえる","category":"Contrast & Conditions","usages":[{"usage":"Can be heard; is audible","japanese":"あなたの言ったことが聞こえなかったよ。","reading":"あなたのいったことがきこえなかったよ。","english":"I didn't hear what you said."}]},{"id":183,"level":"N4","expression":"見える","meaning":"Can be seen; is visible","format":"Object / scene + が見える","category":"Other Expressions","usages":[{"usage":"Can be seen; is visible","japanese":"何も見えないので電気をつけてください。","reading":"なにもみえないのででんきをつけてください。","english":"I can't see anything so please turn on the lights."},{"usage":"Looks (like) A; looks similar to A","japanese":"彼女はいつも笑っていて楽しそうに見えるね。","reading":"かのじょはいつもわらっていてたのしそうにみえるね。","english":"She is always laughing and looking like she's having fun."}]},{"id":184,"level":"N3","expression":"ようとしない","meaning":"A isn't being done; not trying to A","format":"Verb volitional form + としない","category":"Verb Forms & Conjugation","usages":[{"usage":"A isn't being done; not trying to A","japanese":"彼は意見の主張ばかりして話し合いをしようとしない。","reading":"かれはいけんのしゅちょうばかりしてはなしあいをしようとしない。","english":"He just asserts his opinion and makes no attempts to discuss things."}]},{"id":185,"level":"N3","expression":"V-ようとする","meaning":"Be about to A; Try to A","format":"Verb volitional form + とする","category":"Verb Forms & Conjugation","usages":[{"usage":"Be about to A; Try to A","japanese":"ジェーンはまさに家から出ようとしていた。","reading":"ジェーンはまさにいえからでようとしていた。","english":"Jane was about to leave the house."}]},{"id":186,"level":"N3","expression":"V-ようと思う","meaning":"I think I will A","format":"Verb volitional form + と思う","category":"Verb Forms & Conjugation","usages":[{"usage":"I think I will A","japanese":"外国に行こうと思っている。","reading":"がいこくにいこうとおもっている。","english":"I'm thinking I'll go abroad."}]},{"id":187,"level":"N3","expression":"いくら~ても","meaning":"No matter (how much) A","format":"いくら + Verb て-form + も / い-adj (-く) + ても / な-adj・Noun + でも","category":"Verb Forms & Conjugation","usages":[{"usage":"No matter (how much) A","japanese":"いくら私が寛容でも許せないこともある。","reading":"いくらわたしがかんようでもゆるせないこともある。","english":"No matter how open-minded I am, there are things that I cannot forgive."}]},{"id":188,"level":"N3","expression":"うち／ないうち","meaning":"While A is the case, B; While A is occurring, B","format":"Verb dictionary form / ている / い-adj / な-adj + な / Noun + の + うちに; Verb ない-form + うちに","category":"Verb Forms & Conjugation","usages":[{"usage":"While A is the case, B; While A is occurring, B","japanese":"スープは熱いうちに召し上がってください。","reading":"スープはあついうちにめしあがってください。","english":"Eat your soup while it is hot."},{"usage":"While A is not occurring, B","japanese":"彼がこないうちにご飯は全部食べられてしまった。","reading":"かれがこないうちにごはんはぜんぶたべられてしまった。","english":"All of the food at the dinner had been eaten before he arrived."}]},{"id":189,"level":"N3","expression":"おかげで","meaning":"Because of A, (positive result) B; Thanks to A, B","format":"Verb / い-adj plain + おかげで; Noun + の / な-adj + な + おかげで","category":"Reasons & Causes","usages":[{"usage":"Because of A, (positive result) B; Thanks to A, B","japanese":"毎日運動するおかげですごく高く跳べます。","reading":"まいにちうんどうするおかげですごくたかくとべます。","english":"Because I exercise everyday, I can jump amazingly high."}]},{"id":190,"level":"N3","expression":"掛けの／掛けだ","meaning":"B in the middle of A; half-A B","format":"Verb ます-stem + かけの + Noun; Verb ます-stem + かけだ","category":"Other Expressions","usages":[{"usage":"B in the middle of A; half-A B","japanese":"食べ掛けの給食をちゃんと食べなさい！","reading":"たべかけのきゅうしょくをちゃんとたべなさい！","english":"Finish eating your school lunch! (which you're partway through)"}]},{"id":191,"level":"N3","expression":"かもしれない","meaning":"Might A; maybe A; perhaps A","format":"Plain-form clause + かもしれない; Noun / な-adj + かもしれない","category":"Verb Forms & Conjugation","usages":[{"usage":"Might A; maybe A; perhaps A","japanese":"それは本当かもしれない。","reading":"それはほんとうかもしれない。","english":"It may be true."}]},{"id":192,"level":"N3","expression":"から〜にかけて","meaning":"From A through B","format":"Place / time + から + place / time + にかけて","category":"Verb Forms & Conjugation","usages":[{"usage":"From A through B","japanese":"昨日の地震は北海道から宮城にかけて揺れが感じられました。","reading":"きのうのじしんはほっかいどうからみやぎにかけてゆれがかんじられました。","english":"The tremors from yesterday's earthquake could be felt from Hokkaido to Miyagi."}]},{"id":193,"level":"N3","expression":"か何か","meaning":"A or something","format":"Noun + か何か","category":"Other Expressions","usages":[{"usage":"A or something","japanese":"お腹が空いたね。パンか何かあったっけ？","reading":"おなかがすいたね。パンかなにかあったっけ？","english":"I'm hungry. Do we have bread or something?"}]},{"id":194,"level":"N3","expression":"がっている","meaning":"Wants to A","format":"Verb ます-stem + たがっている; い-adj (-い) / な-adj stem + がっている","category":"Verb Forms & Conjugation","usages":[{"usage":"Wants to A","japanese":"ずっとパパの車に乗りたがってたのよね。今日は幼稚園まで車で送ってってよ。","reading":"ずっとパパのくるまにのりたがってたのよね。きょうはようちえんまでくるまでおくってってよ。","english":"She's always wanted to ride in Daddy (your)'s car. She asked for you to take her to kindergarten today."},{"usage":"Shows signs of state/condition A","japanese":"あやちゃんは何かを欲しがっている。","reading":"あやちゃんはなにかをほしがっている。","english":"It seems like Aya wants something."},{"usage":"Don't be A (afraid, shy, etc.)","japanese":"そんなに恥ずかしがらないで堂々とスピーチしてください。","reading":"そんなにはずかしがらないでどうどうとスピーチしてください。","english":"Don't be so shy and please give a great speech."}]},{"id":195,"level":"N3","expression":"きり","meaning":"Only A (small number of something)","format":"Noun / number + きり; Verb た-form + きり","category":"Other Expressions","usages":[{"usage":"Only A (small number of something)","japanese":"私たちは二人切りで頑張ってきました。","reading":"わたしたちはふたりきりでがんばってきました。","english":"We did our best, just the two of us."}]},{"id":196,"level":"N3","expression":"きれない","meaning":"Can't finish/complete A","format":"Verb ます-stem + きれない","category":"Verb Forms & Conjugation","usages":[{"usage":"Can't finish/complete A","japanese":"この部屋に５０人は入り切れない。","reading":"このへやに５０にんははいりきれない。","english":"This room is too small to contain 50 people."}]},{"id":197,"level":"N3","expression":"くせに","meaning":"Even though A, unfortunate result/state B","format":"Verb / い-adj plain + くせに; Noun + の / な-adj + な + くせに","category":"Contrast & Conditions","usages":[{"usage":"Even though A, unfortunate result/state B","japanese":"姉は母に掃除を頼まれたくせに、私にさせた。","reading":"あねはははにそうじをたのまれたくせに、わたしにさせた。","english":"Even though mom asked my big sister to clean, she made me do it."}]},{"id":198,"level":"N3","expression":"くらい／ぐらい","meaning":"So A; to the extent A","format":"Plain-form clause + くらい / ぐらい; quantity + くらい","category":"Limits & Degree","usages":[{"usage":"So A; to the extent A","japanese":"あなたには感謝してもしきれないくらいだ。","reading":"あなたにはかんしゃしてもしきれないくらいだ。","english":"I cannot thank you enough."},{"usage":"A non-exact amount A; Around/about A","japanese":"３分くらいでカップラーメンができるよ。","reading":"３ぷんくらいでカップラーメンができるよ。","english":"You can make cup ramen in about three minutes."},{"usage":"At least A","japanese":"掃除くらいしてくれない？","reading":"そうじくらいしてくれない？","english":"Could you at least clean?"}]},{"id":199,"level":"N3","expression":"くれと","meaning":"Asked to (do/don't do) A","format":"Verb て-form + くれと + 頼む / 言う (quoted request)","category":"Particles & Connectors","usages":[{"usage":"Asked to (do/don't do) A","japanese":"新しいプロジェクトのリーダーになってくれと頼まれたよ。","reading":"あたらしいプロジェクトのリーダーになってくれとたのまれたよ。","english":"I was asked to become the new project's leader."}]},{"id":200,"level":"N3","expression":"こそ","meaning":"A (often a reason/cause) is very strongly emphasized.","format":"Noun + こそ; だからこそ","category":"Other Expressions","usages":[{"usage":"A (often a reason/cause) is very strongly emphasized.","japanese":"だからこそ、車で行くなといったんですよ。","reading":"だからこそ、くるまでいくなといったんですよ。","english":"That's why I told you not to go by car."}]},{"id":201,"level":"N3","expression":"ことか","meaning":"How A; so A; how much A!","format":"Interrogative + Verb / adjective + ことか (exclamation)","category":"Particles & Connectors","usages":[{"usage":"How A; so A; how much A!","japanese":"その部屋はなんて寒かったことか。","reading":"そのへやはなんてさむかったことか。","english":"How cold it was in the room!"}]},{"id":202,"level":"N3","expression":"ことだ","meaning":"A is necessary/good (offering advice/suggestion)","format":"Verb dictionary form / ない-form + ことだ (advice); い-adj / な-adj + ことだ (exclamation)","category":"Particles & Connectors","usages":[{"usage":"A is necessary/good (offering advice/suggestion)","japanese":"海外に住む間は両親に時々連絡することだ。","reading":"かいがいにすむあいだはりょうしんにときどきれんらくすることだ。","english":"You should get in contact with your parents sometimes while you're living overseas."},{"usage":"How A. (states a somewhat strong feeling)","japanese":"合格とは素晴らしいことだ。","reading":"ごうかくとはすばらしいことだ。","english":"How wonderful it is to pass (e.g. a test)"}]},{"id":203,"level":"N3","expression":"ことにする","meaning":"Decide to A","format":"Verb dictionary form / ない-form + ことにする; ～ことにしている","category":"Verb Forms & Conjugation","usages":[{"usage":"Decide to A","japanese":"あの人はあまり好きじゃないので話さないことにする。","reading":"あのひとはあまりすきじゃないのではなさないことにする。","english":"I'm not going to talk to that person because I don't like him."},{"usage":"To make a rule/habit of A","japanese":"私は６時に起きることにしている。","reading":"わたしは６じにおきることにしている。","english":"I make it a rule to get up at six."}]},{"id":204,"level":"N3","expression":"ことになる","meaning":"To be decided that A; A is decided (by someone else)","format":"Verb dictionary form / ない-form + ことになる","category":"Verb Forms & Conjugation","usages":[{"usage":"To be decided that A; A is decided (by someone else)","japanese":"昨日の会議で、パーティーが２１日に行われることになりました。","reading":"きのうのかいぎで、パーティーが２１にちにおこなわれることになりました。","english":"It was decided at the meeting yesterday to have the party on the 21st."},{"usage":"Shows a natural/logical conclusion A","japanese":"後十分歩いたら、今日は一時間運動したことになる。","reading":"あとじゅっぷんあるいたら、きょうはいちじかんうんどうしたことになる。","english":"If you walk ten more minutes, you will have exercised an hour today."}]},{"id":205,"level":"N3","expression":"ことは〜が","meaning":"Although A is true, C","format":"Verb / adjective plain + ことは + same predicate + が / けど","category":"Contrast & Conditions","usages":[{"usage":"Although A is true, C","japanese":"この車はいいことはいいが燃費が悪い。","reading":"このくるまはいいことはいいがねんぴがわるい。","english":"This car has its good points, but its gas mileage is bad."}]},{"id":206,"level":"N3","expression":"ことはない","meaning":"A is not necessary; it's OK if A is not done.","format":"Verb dictionary form + ことはない","category":"Verb Forms & Conjugation","usages":[{"usage":"A is not necessary; it's OK if A is not done.","japanese":"いいえ、謝ることはないよ。","reading":"いいえ、あやまることはないよ。","english":"No, there's no need to apologize."}]},{"id":207,"level":"N3","expression":"さ","meaning":"Changes A into a noun","format":"い-adjective (-い) + さ; な-adjective stem + さ (nominalization)","category":"Other Expressions","usages":[{"usage":"Changes A into a noun","japanese":"それの高さはいくらですか。","reading":"それのたかさはいくらですか。","english":"What is the height of that?"}]},{"id":208,"level":"N3","expression":"さ","meaning":"Emphasizes the words/sentence A that precedes it (similar to よ)","format":"Sentence + さ (casual sentence-ending particle)","category":"Other Expressions","usages":[{"usage":"Emphasizes the words/sentence A that precedes it (similar to よ)","japanese":"あのさ、ちょっと話す時間ある？","reading":"あのさ、ちょっとはなすじかんある？","english":"Hey, do you have a bit of time to talk?"}]},{"id":209,"level":"N3","expression":"さえ／にさえ／でさえ","meaning":"Even A","format":"Noun + さえ / にさえ / でさえ","category":"Limits & Degree","usages":[{"usage":"Even A","japanese":"この問題は、子供でさえ答えられるほど易しい。","reading":"このもんだいは、こどもでさえこたえられるほどやさしい。","english":"This question is so easy that even a child can answer it."}]},{"id":210,"level":"N3","expression":"させていただきたい","meaning":"I want you to let me A","format":"Verb causative て-form + いただきたい (respectful permission request)","category":"Verb Forms & Conjugation","usages":[{"usage":"I want you to let me A","japanese":"私に説明させていただきたい。","reading":"わたしにせつめいさせていただきたい。","english":"Please allow me to explain."}]},{"id":211,"level":"N3","expression":"させてください","meaning":"Please let me A; Please allow me to A","format":"Verb causative て-form + ください (permission request)","category":"Verb Forms & Conjugation","usages":[{"usage":"Please let me A; Please allow me to A","japanese":"提出前に確認させてください。","reading":"ていしゅつまえにかくにんさせてください。","english":"Please allow me to check it over before it is submitted."}]},{"id":212,"level":"N3","expression":"しか〜ない","meaning":"Only A; no more than A","format":"Noun + しか + negative predicate; Verb dictionary form + しかない (no alternative)","category":"Verb Forms & Conjugation","usages":[{"usage":"Only A; no more than A","japanese":"すみませんが、日本語の名刺しか持っていないんですけど。","reading":"すみませんが、にほんごのめいししかもっていないんですけど。","english":"Sorry, I only have a Japanese (-language) business card."},{"usage":"There's only A; Only A can be done; Only A (of many methods)","japanese":"彼女に騙されてしまったので別れるしかないです。","reading":"かのじょにだまされてしまったのでわかれるしかないです。","english":"I was deceived by her, so there is nothing to do but go our separate ways."}]},{"id":213,"level":"N3","expression":"じゃない/ではない","meaning":"A, right?; A, isn't it?","format":"Plain-form clause + じゃない / ではない (confirmation question)","category":"Verb Forms & Conjugation","usages":[{"usage":"A, right?; A, isn't it?","japanese":"もう私たち帰ってもいいんじゃない？","reading":"もうわたしたちかえってもいいんじゃない？","english":"It's OK if we go home already, right?"}]},{"id":214,"level":"N3","expression":"ずつ","meaning":"A of B each ..","format":"Number + counter + ずつ","category":"Other Expressions","usages":[{"usage":"A of B each ..","japanese":"各自1枚ずつプリントを配布します。","reading":"かくじ1まいずつプリントをはいふします。","english":"I will pass out one handout to each person."}]},{"id":215,"level":"N3","expression":"ずに","meaning":"Without A..ing","format":"Verb ない-form (-ない) + ずに; する→せずに","category":"Verb Forms & Conjugation","usages":[{"usage":"Without A..ing","japanese":"ノックをせずに私の部屋に入ってくるな。","reading":"ノックをせずにわたしのへやにはいってくるな。","english":"Don't come into my room without knocking."}]},{"id":216,"level":"N3","expression":"せいで／せいか","meaning":"Because of A, B","format":"Verb / い-adj plain + せいで / せいか; Noun + の / な-adj + な + せいで","category":"Reasons & Causes","usages":[{"usage":"Because of A, B","japanese":"彼女が私を騙したせいで、別れなければならなかった。","reading":"かのじょがわたしをだましたせいで、わかれなければならなかった。","english":"We had to break up, because she deceived me."}]},{"id":217,"level":"N3","expression":"その為","meaning":"Because of A, B","format":"Clause A。そのため、clause B。","category":"Other Expressions","usages":[{"usage":"Because of A, B","japanese":"昨日は雪が多く降りました。その為交通機関に遅れが出ています。","reading":"きのうはゆきがおおくふりました。そのためこうつうきかんにおくれがでています。","english":"It snowed a lot yesterday. Hence, there are delays with the transportation."}]},{"id":218,"level":"N3","expression":"その上","meaning":"Not only A, but B (as well)","format":"Clause A。その上、clause B。","category":"Other Expressions","usages":[{"usage":"Not only A, but B (as well)","japanese":"彼はよく考える人です。その上行動力もあります。","reading":"かれはよくかんがえるひとです。そのうえこうどうりょくもあります。","english":"He's a person who thinks carefully. Furthermore, he's able to take action."}]},{"id":219,"level":"N3","expression":"その結果","meaning":"Because of A (in the past), B","format":"Clause A。その結果、clause B。","category":"Reasons & Causes","usages":[{"usage":"Because of A (in the past), B","japanese":"彼は一切の運動を止めてしまった。その結果太りはじめました。","reading":"かれはいっさいのうんどうをやめてしまった。そのけっかふとりはじめました。","english":"He's completely quit exercising. Consequently, he's started to get fat."}]},{"id":220,"level":"N3","expression":"それと","meaning":"A, and B","format":"Clause A。それと、clause B。","category":"Particles & Connectors","usages":[{"usage":"A, and B","japanese":"サラダ油買ってきてくれない？あ、それと牛乳も！","reading":"サラダあぶらかってきてくれない？あ、それとぎゅうにゅうも！","english":"Would you buy some salad oil for me? Ah, and some milk, too!"}]},{"id":221,"level":"N3","expression":"それとも","meaning":"A? or B?","format":"Question / alternative A、それとも alternative B?","category":"Particles & Connectors","usages":[{"usage":"A? or B?","japanese":"お昼、ラーメンか、それともおそばか、どっちがいい？","reading":"おひる、ラーメンか、それともおそばか、どっちがいい？","english":"For lunch, which do you want: ramen or soba?"}]},{"id":222,"level":"N3","expression":"立て","meaning":"Just after A (has been done)","format":"Verb ます-stem + たての + Noun (freshly made)","category":"Verb Forms & Conjugation","usages":[{"usage":"Just after A (has been done)","japanese":"淹れ立てのコーヒーはいかがですか？","reading":"いれたてのコーヒーはいかがですか？","english":"How about some freshly made coffee?"}]},{"id":223,"level":"N3","expression":"たとえ〜ても","meaning":"Even if A is the case","format":"たとえ + Verb て-form + も / い-adj (-く) + ても / Noun・な-adj + でも","category":"Verb Forms & Conjugation","usages":[{"usage":"Even if A is the case","japanese":"たとえ飢えかかっていても、彼は助けを頼みたがらなかった。","reading":"たとえうえかかっていても、かれはたすけをたのみたがらなかった。","english":"He didn't like to ask for help even if he was starving."}]},{"id":224,"level":"N3","expression":"たとたん","meaning":"As soon as A (occured), B","format":"Verb た-form + とたん(に)、B","category":"Time & Sequence","usages":[{"usage":"As soon as A (occured), B","japanese":"その物音を聞いたとたんに、私の弟は泣きだした。","reading":"そのものおとをきいたとたんに、わたしのおとうとはなきだした。","english":"On hearing the noise, my brother started to cry."}]},{"id":225,"level":"N3","expression":"度に","meaning":"Every time that A (occurs)","format":"Verb dictionary form / Noun + の + たびに","category":"Time & Sequence","usages":[{"usage":"Every time that A (occurs)","japanese":"この写真を見る度に私の父を思い出す。","reading":"このしゃしんをみるたびにわたしのちちをおもいだす。","english":"Every time I see this picture, I remember my father."}]},{"id":226,"level":"N3","expression":"たまえ","meaning":"Please do A","format":"Verb ます-stem + たまえ (command, old-fashioned)","category":"Other Expressions","usages":[{"usage":"Please do A","japanese":"もう子供ではないのだから朝は自分で起きたまえ。","reading":"もうこどもではないのだからあさはじぶんでおきたまえ。","english":"You're no longer a child, so please wake up on your own in the morning."}]},{"id":227,"level":"N3","expression":"たもの","meaning":"Shows past habit or action A that was done often","format":"Verb た-form + ものだ (past habit / nostalgia)","category":"Particles & Connectors","usages":[{"usage":"Shows past habit or action A that was done often","japanese":"昔はこの空き地でも子供たちが遊んでいたものだ。","reading":"むかしはこのあきちでもこどもたちがあそんでいたものだ。","english":"In the old days kids used to play even in this vacant land."}]},{"id":228,"level":"N3","expression":"だい","meaning":"Turns sentence A into a question (casual).","format":"Plain-form clause + だい (casual masculine-style ending)","category":"Questions & Expressions","usages":[{"usage":"Turns sentence A into a question (casual).","japanese":"なぜ君は僕に冷たいんだい？","reading":"なぜきみはぼくにつめたいんだい？","english":"Why are you cold with me ?"},{"usage":"Used by young males to make an assertion (ending in A)","japanese":"僕だったら大丈夫だい。","reading":"ぼくだったらだいじょうぶだい。","english":"I'd be fine if it was me."}]},{"id":229,"level":"N3","expression":"だけしか","meaning":"Only A can B","format":"Noun + だけしか + negative predicate (emphatic restriction)","category":"Limits & Degree","usages":[{"usage":"Only A can B","japanese":"","reading":"","english":""}]},{"id":230,"level":"N3","expression":"だけど","meaning":"A, however/but B","format":"Clause A。だけど、clause B。","category":"Limits & Degree","usages":[{"usage":"A, however/but B","japanese":"だけど急にどうしてそんなことを言うの？","reading":"だけどきゅうにどうしてそんなことをいうの？","english":"But, why would you say such a thing so suddenly?"}]},{"id":231,"level":"N3","expression":"っけ","meaning":"Marks a question (very informal)","format":"Plain-form clause + っけ (recollection / checking)","category":"Questions & Expressions","usages":[{"usage":"Marks a question (very informal)","japanese":"今日は雨が降るんだっけ？","reading":"きょうはあめがふるんだっけ？","english":"Is it going to rain today?"},{"usage":"Used to trying to recall/confirm information A; 'What is it; again?'","japanese":"お母さん出かけたっけ？","reading":"おかあさんでかけたっけ？","english":"Mom headed out, right?"}]},{"id":232,"level":"N3","expression":"っぽい","meaning":"Seems A; A-ish","format":"Noun / adjective stem / Verb ます-stem + っぽい","category":"Other Expressions","usages":[{"usage":"Seems A; A-ish","japanese":"妹はいつも男の子とサッカーをしているから、何だか男の子っぽい。","reading":"いもうとはいつもおとこのことサッカーをしているから、なんだかおとこのこっぽい。","english":"My little sister is always playing soccer with boys, so she seems a little boyish."}]},{"id":233,"level":"N3","expression":"ついでに","meaning":"Since A happened/is going to happen, B","format":"Verb dictionary form / た-form + ついでに; Noun + のついでに","category":"Particles & Connectors","usages":[{"usage":"Since A happened/is going to happen, B","japanese":"なおと君の家へ遊びに行くついでになおと君のお母さんから借りたDVDを返しなさい！","reading":"なおとくんのいえへあそびにいくついでになおとくんのおかあさんからかりたDVDをかえしなさい！","english":"Since you're going to Naoto's house, please return that DVD that you borrowed from his mother."}]},{"id":234,"level":"N3","expression":"つまり","meaning":"A, in other words, B","format":"Clause A。つまり、clause B。","category":"Other Expressions","usages":[{"usage":"A, in other words, B","japanese":"今日は雨が降りました。つまり、マラソン大会は延期となります。","reading":"きょうはあめがふりました。つまり、マラソンたいかいはえんきとなります。","english":"It rained today. In other words, the marathon will be postponed."}]},{"id":235,"level":"N3","expression":"つもりだ","meaning":"Plan to A; be going to A; intend to do A","format":"Verb dictionary form / ない-form + つもりだ; Noun + のつもり","category":"Verb Forms & Conjugation","usages":[{"usage":"Plan to A; be going to A; intend to do A","japanese":"何をするつもりですか？変なことは止めてください！","reading":"なにをするつもりですか？へんなことはやめてください！","english":"What are you going to do? Please don't do anything weird!"},{"usage":"Supposed to be A; intended to be A; assumed to be A","japanese":"これはほんの冗談のつもりだった。","reading":"これはほんのじょうだんのつもりだった。","english":"It was meant as merely a joke."},{"usage":"Intending to A","japanese":"私は東京で一人暮らしをするつもりで、お金を貯めてきた。","reading":"わたしはとうきょうでひとりぐらしをするつもりで、おかねをためてきた。","english":"Intending to live on my own in Tokyo, I saved my money."}]},{"id":236,"level":"N3","expression":"て,で(てform)","meaning":"Since A; As A","format":"Verb て/で-form + following clause (sequence / reason / connection)","category":"Verb Forms & Conjugation","usages":[{"usage":"Since A; As A","japanese":"先週、腐った牛乳を飲んで、お腹を壊しました。","reading":"せんしゅう、くさったぎゅうにゅうをのんで、おなかをこわしました。","english":"Since I drank sour milk last week I had a stomachache."},{"usage":"A, then B","japanese":"昨日は勉強してテレビを見ました。","reading":"きのうはべんきょうしてテレビをみました。","english":"I studied and watched TV yesterday."},{"usage":"A and B","japanese":"あたりは夕方になると寒くて暗くなりました。","reading":"あたりはゆうがたになるとさむくてくらくなりました。","english":"In the evening, the area became cold and dark."},{"usage":"Do B by means of A","japanese":"ラーメンは箸を使って食べます。","reading":"ラーメンははしをつかってたべます。","english":"I eat ramen with chopsticks (lit: by using chopsticks)."}]},{"id":237,"level":"N3","expression":"てご覧","meaning":"Please (try and) A","format":"Verb て-form + ご覧 (casual invitation to try)","category":"Verb Forms & Conjugation","usages":[{"usage":"Please (try and) A","japanese":"ほら、この赤い花を見てごらん。","reading":"ほら、このあかいはなをみてごらん。","english":"Hey, take a look at this red flower."}]},{"id":238,"level":"N3","expression":"てすみません","meaning":"Sorry for doing A; Sorry for having done A","format":"Verb て-form + すみません","category":"Verb Forms & Conjugation","usages":[{"usage":"Sorry for doing A; Sorry for having done A","japanese":"遅刻してすみません","reading":"ちこくしてすみません","english":"Sorry for being late."}]},{"id":239,"level":"N3","expression":"てはいけない","meaning":"May not A; must not A","format":"Verb て-form + はいけない","category":"Verb Forms & Conjugation","usages":[{"usage":"May not A; must not A","japanese":"お父さんに逆らってはいけない。","reading":"おとうさんにさからってはいけない。","english":"Don't go against your father."},{"usage":"In order to avoid A; A would be bad, and so…","japanese":"その花瓶は落とすといけないから、私が持ちますね。","reading":"そのかびんはおとすといけないから、わたしがもちますね。","english":"It would be bad to drop that vase, so I'll carry it (e.g. instead of you)."}]},{"id":240,"level":"N3","expression":"て初めて","meaning":"Only after A did (I) B","format":"Verb て-form + 初めて + clause","category":"Verb Forms & Conjugation","usages":[{"usage":"Only after A did (I) B","japanese":"傷ついて初めて本当の恋だと分かる。","reading":"きずついてはじめてほんとうのこいだとわかる。","english":"I was hurt and knew real love for the first time."}]},{"id":241,"level":"N3","expression":"てばかりいる","meaning":"Always doing A","format":"Verb て-form + ばかりいる","category":"Verb Forms & Conjugation","usages":[{"usage":"Always doing A","japanese":"父は出張で家を空けてばかりいます。","reading":"ちちはしゅっちょうでいえをあけてばかりいます。","english":"Dad is always away on business trips."}]},{"id":242,"level":"N3","expression":"て欲しい","meaning":"I want (person, thing) A to B (action)","format":"Verb て-form + ほしい","category":"Verb Forms & Conjugation","usages":[{"usage":"I want (person, thing) A to B (action)","japanese":"この書類を今すぐ彼女に届けて欲しい。","reading":"このしょるいをいますぐかのじょにとどけてほしい。","english":"I want you to take this paper to her right away."},{"usage":"Want A to not B","japanese":"この部屋でタバコを吸わないで欲しいです。","reading":"このへやでタバコをすわないでほしいです。","english":"I don't want you to smoke in this room."},{"usage":"Would love for A to (not) happen","japanese":"身だしなみにはいつも気をつけて欲しいものだ。","reading":"みだしなみにはいつもきをつけてほしいものだ。","english":"I would really like for you to always pay attention to your personal appearance."}]},{"id":243,"level":"N3","expression":"ても始まらない","meaning":"There is no point/use in doing A","format":"Verb て-form + も始まらない","category":"Verb Forms & Conjugation","usages":[{"usage":"There is no point/use in doing A","japanese":"過去の失敗を後悔しても始まらないよ。また頑張ろうよ。","reading":"かこのしっぱいをこうかいしてもはじまらないよ。またがんばろうよ。","english":"There is no use in regretting your past mistakes. Try again and do your best!"}]},{"id":244,"level":"N3","expression":"てもらいたい","meaning":"I'd like you to A (for me)","format":"Verb て-form + もらいたい","category":"Verb Forms & Conjugation","usages":[{"usage":"I'd like you to A (for me)","japanese":"少し話してもらいたいのですが、お願いできますか？","reading":"すこしはなしてもらいたいのですが、おねがいできますか？","english":"I'd like to have you speak for a bit, can I ask you to do that?"}]},{"id":245,"level":"N3","expression":"ですから","meaning":"Because of A, B","format":"Sentence A。ですから、sentence B。","category":"Reasons & Causes","usages":[{"usage":"Because of A, B","japanese":"彼女の家は会社から大分離れています。ですから彼女は毎日４０分掛けて歩いてきます。","reading":"かのじょのいえはかいしゃからだいぶはなれています。ですからかのじょはまいにち４０ぷんかけてあるいてきます。","english":"Her house is pretty far from her work. Because of that, it takes her 40 minutes to walk each day."}]},{"id":246,"level":"N3","expression":"と","meaning":"When/if A, then B","format":"Verb dictionary form / ない-form + と (automatic result); Noun + と (and/with)","category":"Particles & Connectors","usages":[{"usage":"When/if A, then B","japanese":"このキノコ、食べると笑いが止まらなくなるんだって。","reading":"このキノコ、たべるとわらいがやまらなくなるんだって。","english":"They say that if you eat this mushroom, you won't be able to stop laughing."},{"usage":"A and B (and C,etc..)","japanese":"このパンと、こっちのケーキ、どちらも食べたいです。","reading":"このパンと、こっちのケーキ、どちらもたべたいです。","english":"I want to eat both this bread and this cake."},{"usage":"With A; to A","japanese":"私は彼と映画に行きました。","reading":"わたしはかれとえいがにいきました。","english":"I went to a movie with him."},{"usage":"Shows a sequence of two events A and B","japanese":"少し走ると息が切れた。","reading":"すこしはしるといきがきれた。","english":"I ran a bit and I ran out of breath."},{"usage":"When/if A (polite/formal version)","japanese":"私は明日ですと、一日中空いています。","reading":"わたしはあしたですと、いちにちじゅうあいています。","english":"If it's tomorrow, I'm open (available) all day."}]},{"id":247,"level":"N3","expression":"といい","meaning":"It would be nice if A; I wish A; I hope A","format":"Verb dictionary form / ない-form + といい (hope / suggestion)","category":"Particles & Connectors","usages":[{"usage":"It would be nice if A; I wish A; I hope A","japanese":"困っている人がいたら助けるといいです。","reading":"こまっているひとがいたらたすけるといいです。","english":"If there's someone in trouble it's good to help them."}]},{"id":248,"level":"N3","expression":"という","meaning":"B is called A","format":"Noun + という + Noun; clause + という + Noun","category":"Particles & Connectors","usages":[{"usage":"B is called A","japanese":"「桜」という曲、聞いたことあるの？","reading":"「さくら」というきょく、きいたことあるの？","english":"Have you ever heard the song called \"Sakura\"?"},{"usage":"All A; every A; this (very) A","japanese":"この時期の家という家はクリスマスの飾りで輝いている。","reading":"このじきのいえといういえはクリスマスのかざりでかがやいている。","english":"In this season, every house shines with Christmas decorations."},{"usage":"A is information about B","japanese":"近所に新しいパン屋さんができるという話を聞いた？","reading":"きんじょにあたらしいパンやさんができるというはなしをきいた？","english":"Did you hear the talk about the new bakery opening in the neighborhood?"},{"usage":"It's said that A (hearsay, rumor, report, or legend)","japanese":"昔この池に河童がいたという。","reading":"むかしこのいけにかっぱがいたという。","english":"It's said that there was a kappa (mythical creature) in this pond long ago."}]},{"id":249,"level":"N3","expression":"ということ","meaning":"Changes sentence/phrase A into a noun","format":"Plain-form clause + ということ","category":"Particles & Connectors","usages":[{"usage":"Changes sentence/phrase A into a noun","japanese":"運転するということは得意ね。","reading":"うんてんするということはとくいね。","english":"He's good at driving, isn't he?"},{"usage":"Presents information A; A is heard (and repeated in this sentence)","japanese":"噂によれば、今年のクラブに入る１年生の人数は大変多いということです。","reading":"うわさによれば、ことしのクラブにはいる１ねんせいのにんずうはたいへんおおいということです。","english":"According to the rumors, it looks like that there are a lot of first year students joining clubs this year."}]},{"id":250,"level":"N3","expression":"というより","meaning":"Rather than A","format":"Plain-form clause + というより + B","category":"Particles & Connectors","usages":[{"usage":"Rather than A","japanese":"弟は昨日の試験に落ちた。頭がよくないと言うより全然勉強しなかったせいだ。","reading":"おとうとはきのうのしけんにおちた。あたまがよくないというよりぜんぜんべんきょうしなかったせいだ。","english":"My little brother failed the exam yesterday. Rather than saying that he is not smart, it is because he did not study at all."}]},{"id":251,"level":"N3","expression":"とく","meaning":"To do A in advance","format":"Verb て-form + おく → とく (colloquial)","category":"Particles & Connectors","usages":[{"usage":"To do A in advance","japanese":"洗濯しといたから、後干しといてね。","reading":"せんたくしといたから、あとほしといてね。","english":"I went ahead and did the laundry, so put it out to dry, ok?"}]},{"id":252,"level":"N3","expression":"ところ","meaning":"About to A","format":"Verb dictionary form + ところ; Verb ている + ところ; Verb た + ところ","category":"Particles & Connectors","usages":[{"usage":"About to A","japanese":"しおりさんが発表するところだからよく聞きなさい。","reading":"しおりさんがはっぴょうするところだからよくききなさい。","english":"Shiori is about to present, so listen well."},{"usage":"Be now A...ing (be in the middle of doing A)","japanese":"私たちが訪ねた時、彼は兄さんに英語を教えてもらっているところであった。","reading":"わたしたちがたずねたとき、かれはあにさんにえいごをおしえてもらっているところであった。","english":"He was being taught English by his brother when we called on him."},{"usage":"Just finished A; Have been A...ing","japanese":"あなたのボーイフレンドは待ちくたびれて、今帰ったところよ。","reading":"あなたのボーイフレンドはまちくたびれて、いまかえったところよ。","english":"Your boyfriend got tired of waiting for you and left just now."},{"usage":"After A is done, the results of A are B","japanese":"日本の番組をみたところ、すごい事件が起きてるらしい。","reading":"にほんのばんぐみをみたところ、すごいじけんがおきてるらしい。","english":"Judging from the program from Japan, it seems like a major incident is happening."}]},{"id":253,"level":"N3","expression":"ところが","meaning":"Although A (was planned/expected), B (unexpected)","format":"Sentence A。ところが、sentence B。","category":"Contrast & Conditions","usages":[{"usage":"Although A (was planned/expected), B (unexpected)","japanese":"私は来年留学します。ところがパスポートをまだ準備していません。","reading":"わたしはらいねんりゅうがくします。ところがパスポートをまだじゅんびしていません。","english":"I'm going to study abroad next year. However, I haven't prepared my passport yet."}]},{"id":254,"level":"N3","expression":"ところだった","meaning":"Was just about to (do) A; Was just thinking of doing A","format":"Verb dictionary form + ところだった (nearly did)","category":"Other Expressions","usages":[{"usage":"Was just about to (do) A; Was just thinking of doing A","japanese":"僕はあの時帰るところだった。","reading":"ぼくはあのときかえるところだった。","english":"I was just about to head home at that time."}]},{"id":255,"level":"N3","expression":"ところで","meaning":"By the way, A","format":"Sentence A。ところで、sentence B。","category":"Particles & Connectors","usages":[{"usage":"By the way, A","japanese":"ところで、皆さんお腹は減っていませんか？","reading":"ところで、みなさんおなかはへっていませんか？","english":"Well, is everyone hungry?"}]},{"id":256,"level":"N3","expression":"としたら","meaning":"If A were the case; Supposing A","format":"Plain-form clause + としたら / とすれば","category":"Verb Forms & Conjugation","usages":[{"usage":"If A were the case; Supposing A","japanese":"その川を泳いで渡るとしたら、どれだけ時間がかかるだろうか。","reading":"そのかわをおよいでわたるとしたら、どれだけじかんがかかるだろうか。","english":"How long would it take you to swim across the river?"}]},{"id":257,"level":"N3","expression":"として","meaning":"As A; From the standpoint of A","format":"Noun + として / としての + Noun","category":"Verb Forms & Conjugation","usages":[{"usage":"As A; From the standpoint of A","japanese":"青を基調として絵を描いた。","reading":"あおをきちょうとしてえをえがいた。","english":"This picture was drawn with blue as the base color."},{"usage":"Not even A B","japanese":"ここには誰一人としてあなたを疑う者はいない。","reading":"ここにはだれひとりとしてあなたをうたがうものはいない。","english":"Not even a single person here doubts you."}]},{"id":258,"level":"N3","expression":"とは限らない","meaning":"A is not 100%, there are exceptions","format":"Plain-form clause + とは限らない","category":"Verb Forms & Conjugation","usages":[{"usage":"A is not 100%, there are exceptions","japanese":"おいしそうに見える食べ物が必ずしもおいしいとは限らない。","reading":"おいしそうにみえるたべものがかならずしもおいしいとはかぎらない。","english":"Delicious looking food doesn't necessarily taste good."}]},{"id":259,"level":"N3","expression":"といえば／というと／といったら","meaning":"When A is thought about, B soon comes to mind","format":"Noun / phrase + といえば / というと / といったら","category":"Verb Forms & Conjugation","usages":[{"usage":"When A is thought about, B soon comes to mind","japanese":"日本の中で、一番有名な観光地といったら、京都ですね。","reading":"にほんのなかで、いちばんゆうめいなかんこうちといったら、きょうとですね。","english":"When I think about the most famous sightseeing place in Japan, Kyoto comes to mind."},{"usage":"Although A is expected, in reality, it's B","japanese":"これは人気商品かと言うと、そんなに人気はないんだよね。","reading":"これはにんきしょうひんかというと、そんなににんきはないんだよね。","english":"Although I expected this to be a big hit, it really isn't that popular."}]},{"id":260,"level":"N3","expression":"と言っても","meaning":"Although A is the case, B","format":"Plain-form clause + といっても","category":"Verb Forms & Conjugation","usages":[{"usage":"Although A is the case, B","japanese":"旅行といっても隣の町に行った程度です","reading":"りょこうといってもとなりのまちにいったていどです","english":"Although I traveled, it was no farther than to the neighboring towns."}]},{"id":261,"level":"N3","expression":"といわれている","meaning":"It is said by many that A","format":"Plain-form clause + と言われている","category":"Verb Forms & Conjugation","usages":[{"usage":"It is said by many that A","japanese":"あれは古くから神聖な山だと言われている。","reading":"あれはふるくからしんせいなやまだといわれている。","english":"It's said that has been a holy mountain since long ago."}]},{"id":262,"level":"N3","expression":"と言われる","meaning":"(I) was told by A to do(n't) B","format":"Plain-form clause + と言われる","category":"Verb Forms & Conjugation","usages":[{"usage":"(I) was told by A to do(n't) B","japanese":"門限は守れと厳しく言われる。","reading":"もんげんはまもれときびしくいわれる。","english":"I was told sternly to keep (not break) curfew."}]},{"id":263,"level":"N3","expression":"どんなに","meaning":"No matter how (much) A, B","format":"どんなに + Verb て-form + も / adjective + ても","category":"Particles & Connectors","usages":[{"usage":"No matter how (much) A, B","japanese":"どんなに頑張っても英語が上手になりません。","reading":"どんなにがんばってもえいごがじょうずになりません。","english":"No matter how hard I try I'm not getting good at English."}]},{"id":264,"level":"N3","expression":"ないかな/ないかしら","meaning":"I wonder if/suppose A; I fear that A","format":"Verb ない-form + かな / かしら (wish / wondering)","category":"Verb Forms & Conjugation","usages":[{"usage":"I wonder if/suppose A; I fear that A","japanese":"彼女に会ったのは十年ぶりじゃないかしら。","reading":"かのじょにあったのはじゅうねんぶりじゃないかしら。","english":"I suppose that it's been ten years since I last saw her."}]},{"id":265,"level":"N3","expression":"ないことはない","meaning":"There is a (small) possibility of A. A is not impossible.","format":"Verb / adjective ない-form + ことはない","category":"Verb Forms & Conjugation","usages":[{"usage":"There is a (small) possibility of A. A is not impossible.","japanese":"一日に16時間続けて仕事はできないこともないが、全然楽じゃないでしょう？","reading":"いちにちに16じかんつづけてしごとはできないこともないが、ぜんぜんたのじゃないでしょう？","english":"It's not that you can't work 16 hours in a single day, but it's not exactly easy, right?"}]},{"id":266,"level":"N3","expression":"ないと,なくちゃ","meaning":"Must do A","format":"Verb ない-form (-ない) + ないと; Verb なくては → なくちゃ","category":"Verb Forms & Conjugation","usages":[{"usage":"Must do A","japanese":"結婚するなら、山田さん、禁煙しないとだね。","reading":"けっこんするなら、やまださん、きんえんしないとだね。","english":"If you're going to get married, Mr. Yamada, you'll have to stop smoking."}]},{"id":267,"level":"N3","expression":"なぜなら","meaning":"A was done/decided because of B","format":"Clause A。なぜなら、clause B + からだ。","category":"Other Expressions","usages":[{"usage":"A was done/decided because of B","japanese":"私は海に行きたくないんです。なぜなら泳げないからです。","reading":"わたしはうみにいきたくないんです。なぜならおよげないからです。","english":"I don't want to go to the beach. The fact is that I can't swim."}]},{"id":268,"level":"N3","expression":"など,なんて,なんか","meaning":"Marks the end of the non-exhaustive list A","format":"Noun / clause + など / なんて / なんか","category":"Verb Forms & Conjugation","usages":[{"usage":"Marks the end of the non-exhaustive list A","japanese":"この店は食料品、例えばバター、チーズ、砂糖などを売っている。","reading":"このみせはしょくりょうひん、たとえばバター、チーズ、さとうなどをうっている。","english":"The store sells foodstuffs, such as butter, cheese, and sugar."},{"usage":"Things like A; for example A","japanese":"こんな料理など、食べたくないわ。","reading":"こんなりょうりなど、たべたくないわ。","english":"I don't want to eat something like this."},{"usage":"Used to emphasize negative B","japanese":"こんな服なんかいやだよ。","reading":"こんなふくなんかいやだよ。","english":"I don't like clothes like this."},{"usage":"What (did) A","japanese":"今なんて言ったの？","reading":"いまなんていったの？","english":"What did you just say?"},{"usage":"What is the name of A","japanese":"この花はなんていう名前ですか？","reading":"このはなはなんていうなまえですか？","english":"What's the name of this flower?"},{"usage":"How A; What A","japanese":"なんて美しい景色でしょう。","reading":"なんてうつくしいけしきでしょう。","english":"What beautiful scenery."},{"usage":"Shows a strong emotion or feeling about A","japanese":"彼に限って裏切りなどあるものか。","reading":"かれにかぎってうらぎりなどあるものか。","english":"There's just no way he could betray me."}]},{"id":269,"level":"N3","expression":"において","meaning":"At the time/place/state A","format":"Noun + において / における + Noun","category":"Verb Forms & Conjugation","usages":[{"usage":"At the time/place/state A","japanese":"その詩人は人生における美を求めている。","reading":"そのしじんはじんせいにおけるびをもとめている。","english":"That poet searches for the beauty in life."}]},{"id":270,"level":"N3","expression":"にしては","meaning":"For A; even though A; considering A","format":"Verb / い-adj plain + にしては; Noun / な-adj + にしては","category":"Verb Forms & Conjugation","usages":[{"usage":"For A; even though A; considering A","japanese":"８月にしてはとても過ごしやすいね。","reading":"８がつにしてはとてもすごしやすいね。","english":"Passing the time (e.g. in this weather, etc.) is really easy, considering it's August."}]},{"id":271,"level":"N3","expression":"にしても","meaning":"Even for A; In the case of A as well","format":"Verb / い-adj plain + にしても; Noun / な-adj + にしても","category":"Verb Forms & Conjugation","usages":[{"usage":"Even for A; In the case of A as well","japanese":"あなたのおっしゃることは認めるにしても、私はやはりあなたが悪いと存じます。","reading":"あなたのおっしゃることはみとめるにしても、わたしはやはりあなたがわるいとぞんじます。","english":"Even given what you say, I still think you are to blame."}]},{"id":272,"level":"N3","expression":"にとって","meaning":"As for A","format":"Noun + にとって / にとっての + Noun","category":"Verb Forms & Conjugation","usages":[{"usage":"As for A","japanese":"弟は犬が好きだけど僕にとっては嫌いだ。","reading":"おとうとはいぬがすきだけどぼくにとってはきらいだ。","english":"My little brother likes dogs, but (as for me,) I don't."}]},{"id":273,"level":"N3","expression":"には~がいる/ある","meaning":"There is/are B in/at A","format":"Place / situation + には + person + がいる / item + がある","category":"Contrast & Conditions","usages":[{"usage":"There is/are B in/at A","japanese":"日本には富士山がある。","reading":"にほんにはふじさんがある。","english":"Mt. Fuji is in Japan."}]},{"id":274,"level":"N3","expression":"によって/により/による","meaning":"By the means/method A; by A","format":"Noun + によって / により; Noun + による + Noun; Verb passive + によって","category":"Verb Forms & Conjugation","usages":[{"usage":"By the means/method A; by A","japanese":"このプラスチックは火によって損傷を受けない。","reading":"このプラスチックはひによってそんしょうをうけない。","english":"This plastic is not damaged by fire."},{"usage":"In accordance with A; depending on A; based on A; due/because to A","japanese":"この町は自然の残忍な力によって破壊された。","reading":"このまちはしぜんのざんにんなちからによってはかいされた。","english":"This city was ruined by the brutal force of nature."},{"usage":"For some A; certain A","japanese":"患者の状態によっては食べ物を食べやすく細かくする必要がある。","reading":"かんじゃのじょうたいによってはたべものをたべやすくこまかくするひつようがある。","english":"For some patients' conditions, it is necessary to make the food small and easy to eat."},{"usage":"According to A","japanese":"ニュースによると、今夜は雪になるそうだ。","reading":"ニュースによると、こんやはゆきになるそうだ。","english":"According to the news, it'll snow tonight."}]},{"id":275,"level":"N3","expression":"に対して／に対しては","meaning":"In response to (topic) A; in regards to A; considering A; in contrast to A","format":"Noun + に対して / に対しては / に対する + Noun","category":"Verb Forms & Conjugation","usages":[{"usage":"In response to (topic) A; in regards to A; considering A; in contrast to A","japanese":"先生に対して、そういう言いかたは失礼ですよ。","reading":"せんせいにたいして、そういういいかたはしつれいですよ。","english":"It's rude to speak to your teachers that way."}]},{"id":276,"level":"N3","expression":"に比べて／に比べ","meaning":"When compared to A","format":"Noun + に比べて / に比べ","category":"Verb Forms & Conjugation","usages":[{"usage":"When compared to A","japanese":"漢字が六千以上もある中国語に比べて日本語は学びやすいと思います。","reading":"かんじがろくせんいじょうもあるちゅうごくごにくらべてにほんごはまなびやすいとおもいます。","english":"Compared to Chinese with its 6000-plus kanji, I think Japanese is easy to study."}]},{"id":277,"level":"N3","expression":"の","meaning":"Follows A; turning the sentence into a question (casual).","format":"Verb / い-adj plain + の (nominalizer); Noun + の + Noun","category":"Questions & Expressions","usages":[{"usage":"Follows A; turning the sentence into a question (casual).","japanese":"綾子にはその話をきちんと伝えたの？","reading":"あやこにはそのはなしをきちんとつたえたの？","english":"Did you accurately tell Ayako about that discussion?"},{"usage":"A's B (shows possession); the A B","japanese":"彼女のパソコンは古い。","reading":"かのじょのパソコンはふるい。","english":"Her computer is old."},{"usage":"The A one","japanese":"新しい靴は安いのを買うつもりです。","reading":"あたらしいくつはやすいのをかうつもりです。","english":"For my new shoes, I plan on buying inexpensive ones."},{"usage":"A directly modifies B, B of A","japanese":"彼からのメールが久しぶりに届いた。","reading":"かれからのメールがひさしぶりにとどいた。","english":"I got the first email from him in awhile."},{"usage":"B who/that is a(n) A","japanese":"総理大臣の佐藤さんは近所に住んでいる。","reading":"そうりだいじんのさとうさんはきんじょにすんでいる。","english":"The Prime Minister Sato lives nearby."},{"usage":"C which/whose A is B. C's A is B","japanese":"あの髪の長い人は私の妹です。","reading":"あのかみのながいひとはわたしのいもうとです。","english":"That person with the long hair is my younger sister."}]},{"id":278,"level":"N3","expression":"のが","meaning":"A is B","format":"Verb dictionary form / い-adj plain + のが + adjective / 好き","category":"Contrast & Conditions","usages":[{"usage":"A is B","japanese":"亭主が元気で留守なのが一番気楽だ。","reading":"ていしゅがげんきでるすなのがいちばんきらくだ。","english":"I'm the most carefree when my husband is lively and out of the house."}]},{"id":279,"level":"N3","expression":"のこと","meaning":"About A","format":"Noun / person + のこと","category":"Particles & Connectors","usages":[{"usage":"About A","japanese":"娘は最近好きなアニメのことばかり話す。","reading":"むすめはさいきんすきなアニメのことばかりはなす。","english":"Lately, my daughter speaks only about the anime she likes."}]},{"id":280,"level":"N3","expression":"の中","meaning":"Out of the group A, B is the most C","format":"Noun + の中(で / に)","category":"Other Expressions","usages":[{"usage":"Out of the group A, B is the most C","japanese":"兄は成績優秀で、学年の中で一番だ。","reading":"あにはせいせきゆうしゅうで、がくねんのなかでいちばんだ。","english":"My older brother's grades are excellent: he's at the top of his school year."}]},{"id":281,"level":"N3","expression":"はず","meaning":"It should be A; it ought to be A","format":"Verb / い-adj plain + はずだ; Noun + のはず; な-adj + なはず","category":"Particles & Connectors","usages":[{"usage":"It should be A; it ought to be A","japanese":"彼女は宿題を終えてしまったはずだ。","reading":"かのじょはしゅくだいをおえてしまったはずだ。","english":"She ought to have finished her homework."}]},{"id":282,"level":"N3","expression":"はずがない","meaning":"Cannot be A; should not be A (when describing a situation, not the actions of the subject)","format":"Verb / い-adj plain + はずがない; Noun + のはずがない","category":"Verb Forms & Conjugation","usages":[{"usage":"Cannot be A; should not be A (when describing a situation, not the actions of the subject)","japanese":"彼はそれを見たはずがない。","reading":"かれはそれをみたはずがない。","english":"He cannot have seen it."}]},{"id":283,"level":"N3","expression":"はもちろん／はもとより","meaning":"Although A is given/obvious, B (also)","format":"Noun + はもちろん / はもとより + Bも","category":"Other Expressions","usages":[{"usage":"Although A is given/obvious, B (also)","japanese":"彼は、ＣＤプレーヤーはもとよりiPodも持っていないです。","reading":"かれは、ＣＤプレーヤーはもとよりiPodももっていないです。","english":"He doesn't even have a CD player, so naturally he doesn't have an iPod."}]},{"id":284,"level":"N3","expression":"は～となっている","meaning":"A is B, A has been decided to be B","format":"Noun / fact + は + Noun + となっている","category":"Verb Forms & Conjugation","usages":[{"usage":"A is B, A has been decided to be B","japanese":"記録によると、彼がアメリカに渡ったのは2005年となっている。","reading":"きろくによると、かれがアメリカにわたったのは2005ねんとなっている。","english":"According to the records, he came over to the US in 2005."}]},{"id":285,"level":"N3","expression":"は～の一つ","meaning":"A is an example (but not the only one) out of the group B","format":"Noun A + は + Noun B + の一つだ","category":"Particles & Connectors","usages":[{"usage":"A is an example (but not the only one) out of the group B","japanese":"ランニングは代表的なトレーニングの一つだ。","reading":"ランニングはだいひょうてきなトレーニングのひとつだ。","english":"Running is a typical type of training."}]},{"id":286,"level":"N3","expression":"ば〜ほど","meaning":"The more A, C","format":"Verb conditional ば-form / い-adj (-ければ) + same verb/adjective plain + ほど","category":"Limits & Degree","usages":[{"usage":"The more A, C","japanese":"外国語はしゃべればしゃべるほど上手になる。","reading":"がいこくごはしゃべればしゃべるほどじょうずになる。","english":"The more you speak a foreign language, the better you will become."}]},{"id":287,"level":"N3","expression":"ばいい","meaning":"It'd be good to A; should A","format":"Verb conditional ば-form + いい","category":"Other Expressions","usages":[{"usage":"It'd be good to A; should A","japanese":"5時に駅で待っていればいいね。","reading":"5じにえきでまっていればいいね。","english":"It'll be good to be waiting at the station by 5:00."}]},{"id":288,"level":"N3","expression":"ばかり","meaning":"Do only A; do nothing but A","format":"Noun / number + ばかり; Verb た-form + ばかり","category":"Limits & Degree","usages":[{"usage":"Do only A; do nothing but A","japanese":"ゆうこちゃんは笑ってばかりだね。泣いたところを一回も見たことがない。","reading":"ゆうこちゃんはわらってばかりだね。ないたところをいっかいもみたことがない。","english":"Yuuko is always smiling. I haven't seen her crying a single time."},{"usage":"A just finished/ended/occured.","japanese":"私は、テニスを始めたばかりです。","reading":"わたしは、テニスをはじめたばかりです。","english":"I've just started playing tennis."},{"usage":"Shows a continual/continuing negative change A","japanese":"このままでは生活が苦しくなっていくばかりだ。","reading":"このままではせいかつがくるしくなっていくばかりだ。","english":"As it is, our way of living will keep getting difficult."},{"usage":"Around/about A; Approximately A","japanese":"毎日の通勤で往復2時間ばかりかかっています。","reading":"まいにちのつうきんでおうふく2じかんばかりかかっています。","english":"It takes around two hours going to and from work each day."}]},{"id":289,"level":"N3","expression":"ばかりか","meaning":"Not only A, but B as well","format":"Verb / い-adj plain + ばかりか; Noun / な-adj + であるばかりか","category":"Limits & Degree","usages":[{"usage":"Not only A, but B as well","japanese":"母はスペイン語ばかりかイタリア語もしゃべれます。","reading":"はははスペインごばかりかイタリアごもしゃべれます。","english":"My mother not only can speak Spanish, she can speak Italian too."}]},{"id":290,"level":"N3","expression":"ばかりではなく","meaning":"Not only A, not just A","format":"Noun / clause + ばかりではなく、Bも","category":"Limits & Degree","usages":[{"usage":"Not only A, not just A","japanese":"君は秀才であるばかりではなく、音楽の才能もあるのか。","reading":"きみはしゅうさいであるばかりではなく、おんがくのさいのうもあるのか。","english":"Not only are you a bright person, but you have musical talent as well?"}]},{"id":291,"level":"N3","expression":"ふりをする","meaning":"To pretend to (be) A; To act as if A","format":"Verb / い-adj plain + ふりをする; Noun + の / な-adj + な + ふりをする","category":"Particles & Connectors","usages":[{"usage":"To pretend to (be) A; To act as if A","japanese":"上司は偉そうな振りをして堂々とこちらへ歩いてきた。","reading":"じょうしはえらそうなふりをしてどうどうとこちらへあるいてきた。","english":"The boss acted all self-important and strutted over."}]},{"id":292,"level":"N3","expression":"べきだ／べきではない","meaning":"Should do A; Must do A","format":"Verb dictionary form + べきだ / べきではない; する→するべき / すべき","category":"Verb Forms & Conjugation","usages":[{"usage":"Should do A; Must do A","japanese":"小学校の先生は親切で元気であるべきだ。","reading":"しょうがっこうのせんせいはしんせつでげんきであるべきだ。","english":"Elementary school teachers should be kind and energetic."},{"usage":"Should not do A; Must not do A","japanese":"子供の前でタバコを吸うべきではありません。","reading":"こどものまえでタバコをすうべきではありません。","english":"You shouldn't smoke in front of children."}]},{"id":293,"level":"N3","expression":"ほど","meaning":"So much B that it's like A","format":"Plain-form clause / quantity + ほど","category":"Limits & Degree","usages":[{"usage":"So much B that it's like A","japanese":"島国に住んでいるほどシーフードを食べる。","reading":"しまぐににすんでいるほどシーフードをたべる。","english":"They eat so much seafood that it's like they're an islander."},{"usage":"There is nothing as B as A.","japanese":"あの青い鳥ほど高く飛べる動物はいない。","reading":"あのあおいとりほどたかくとべるどうぶつはいない。","english":"There is not an animal that can fly as high as that blue bird."},{"usage":"The more A, B","japanese":"私は彼のことを思うほど幸せになります。","reading":"わたしはかれのことをおもうほどしあわせになります。","english":"The more I think of him the happier I get."},{"usage":"About A; around A (approximation)","japanese":"このズボンの丈を３センチほど長くしてください。","reading":"このズボンのたけを３センチほどながくしてください。","english":"Please make these pants about 3 centimeters longer."}]},{"id":294,"level":"N3","expression":"ほど〜ない","meaning":"A is not as C as B","format":"Noun A + は + Noun B + ほど + negative adjective / verb","category":"Verb Forms & Conjugation","usages":[{"usage":"A is not as C as B","japanese":"月は太陽ほど明るくない。","reading":"つきはたいようほどあかるくない。","english":"The moon is not as bright as the sun."}]},{"id":295,"level":"N3","expression":"ますように","meaning":"(I) hope that A (will come true/happen)","format":"Verb ます-form + ように (prayer / hope)","category":"Verb Forms & Conjugation","usages":[{"usage":"(I) hope that A (will come true/happen)","japanese":"じゅんこちゃんの手術が成功しますように。","reading":"じゅんこちゃんのしゅじゅつがせいこうしますように。","english":"I hope that Junko's surgery will be a success."}]},{"id":296,"level":"N3","expression":"または","meaning":"Both A and B (are acceptable options)","format":"Noun / phrase + または + Noun / phrase","category":"Particles & Connectors","usages":[{"usage":"Both A and B (are acceptable options)","japanese":"私は徒歩または自転車で会社へ行きます。","reading":"わたしはとほまたはじてんしゃでかいしゃへいきます。","english":"I either walk or go by bike to work."}]},{"id":297,"level":"N3","expression":"全く〜ない","meaning":"Not A (at all, even a little bit)","format":"全く + negative predicate","category":"Verb Forms & Conjugation","usages":[{"usage":"Not A (at all, even a little bit)","japanese":"私、英語は少しできますけど、フランス語は全く話せませんよ。","reading":"わたし、えいごはすこしできますけど、フランスごはまったくはなせませんよ。","english":"I can speak a bit of English, but I can't say a word of French."}]},{"id":298,"level":"N3","expression":"まで","meaning":"Until A; up to A; as far as A","format":"Time / place + まで","category":"Time & Sequence","usages":[{"usage":"Until A; up to A; as far as A","japanese":"水が腰まで来た。","reading":"みずがこしまできた。","english":"The water came up to my waist."},{"usage":"Even A","japanese":"彼はスポーツまで得意なんです。","reading":"かれはスポーツまでとくいなんです。","english":"He's even good at sports."}]},{"id":299,"level":"N3","expression":"まま","meaning":"The situation A remains unchanged","format":"Verb た-form / ない-form + まま; Noun + のまま","category":"Other Expressions","usages":[{"usage":"The situation A remains unchanged","japanese":"あなたはそのことを言わないままにして置く方が良い。","reading":"あなたはそのことをいわないままにしておくほうがよい。","english":"It would be better if that remains unsaid."}]},{"id":300,"level":"N3","expression":"まるで～よう","meaning":"(It is almost) As if A","format":"まるで + Noun + のようだ / Verb plain + ようだ","category":"Verb Forms & Conjugation","usages":[{"usage":"(It is almost) As if A","japanese":"綿菓子はまるで雲のようにふわふわだ。","reading":"わたがしはまるでくものようにふわふわだ。","english":"The cotton candy is fluffy, almost as if it's a cloud."}]},{"id":301,"level":"N3","expression":"滅多に~ない","meaning":"There are hardly any A; A is very rare","format":"滅多に + negative predicate","category":"Verb Forms & Conjugation","usages":[{"usage":"There are hardly any A; A is very rare","japanese":"父は仕事で、滅多に帰ってこない。","reading":"ちちはしごとで、めったにかえってこない。","english":"My father almost never comes home from work."}]},{"id":302,"level":"N3","expression":"も~ない","meaning":"Doesn't/didn't A anywhere","format":"Noun + も + negative predicate (not even)","category":"Verb Forms & Conjugation","usages":[{"usage":"Doesn't/didn't A anywhere","japanese":"そんなにおいしい話はどこにもない。","reading":"そんなにおいしいはなはどこにもない。","english":"Such a sweet thing/deal doesn't exist anywhere."},{"usage":"Doesn't/didn't A at all","japanese":"ここで黙っていては何も変わらない。","reading":"ここでだまっていてはなにもかわらない。","english":"If you stay silent nothing will change."},{"usage":"No one A","japanese":"学校にだれも入ったことのない部屋がある。","reading":"がっこうにだれもはいったことのないへやがある。","english":"There's a room in the school that no one has ever entered."}]},{"id":303,"level":"N3","expression":"もし〜たなら","meaning":"If A had happened/was true, If A were to happen/be true","format":"もし + Verb た-form + なら","category":"Other Expressions","usages":[{"usage":"If A had happened/was true, If A were to happen/be true","japanese":"もしここが静かな場所だったら、落ち着いて仕事ができたのになあ。","reading":"もしここがしずかなばしょだったら、おちついてしごとができたのになあ。","english":"If this was a quiet spot, I'd be able to calm down and do my work.."}]},{"id":304,"level":"N3","expression":"もし〜としても","meaning":"Even if A... (chances of A are pretty low)","format":"もし + Plain-form clause + としても","category":"Verb Forms & Conjugation","usages":[{"usage":"Even if A... (chances of A are pretty low)","japanese":"ねぇ、もし彼がここに来たとしても私がいるって言わないでね！","reading":"ねぇ、もしかれがここにきたとしてもわたしがいるっていわないでね！","english":"Even if he comes, don't say that I'm here!"}]},{"id":305,"level":"N3","expression":"もしも〜なら","meaning":"If A..","format":"もしも + Plain-form clause + なら","category":"Other Expressions","usages":[{"usage":"If A..","japanese":"明日もしも時間があったなら、カフェで勉強するつもりだよ。","reading":"あしたもしもじかんがあったなら、カフェでべんきょうするつもりだよ。","english":"If I have time tomorrow, I intend to study at the cafe."}]},{"id":306,"level":"N3","expression":"ように","meaning":"In the hopes that A; in order for A","format":"Verb dictionary / ない-form + ように (purpose); plain-form clause + ように (wish)","category":"Verb Forms & Conjugation","usages":[{"usage":"In the hopes that A; in order for A","japanese":"この花瓶を割らないように注意してください。","reading":"このかびんをわらないようにちゅういしてください。","english":"Please take care not to break this vase."},{"usage":"Please do/don't A","japanese":"７時前にここに来るように。","reading":"７じまえにここにくるように。","english":"Come here before seven o'clock."},{"usage":"As was written/said/etc. in A","japanese":"ここに書いてあるように行動してよ！","reading":"ここにかいてあるようにこうどうしてよ！","english":"Do as is written here!"}]},{"id":307,"level":"N3","expression":"ようにする","meaning":"Try to A; make sure to A","format":"Verb dictionary form / ない-form + ようにする","category":"Verb Forms & Conjugation","usages":[{"usage":"Try to A; make sure to A","japanese":"ねぇ、なるべく早く帰るようにするから、ご飯食べないで待っててよ。","reading":"ねぇ、なるべくはやくかえるようにするから、ごはんたべないでまっててよ。","english":"Hey, I'm going to try and get home as soon as possible, so don't eat and wait for me."}]},{"id":308,"level":"N3","expression":"ようになる／なくなる","meaning":"Come to A (transition over time)","format":"Verb dictionary form / ない-form + ようになる / なくなる","category":"Verb Forms & Conjugation","usages":[{"usage":"Come to A (transition over time)","japanese":"漢字が上手に書けるようになって、うれしかった。","reading":"かんじがじょうずにかけるようになって、うれしかった。","english":"I was delighted to have learned how to write kanji skillfully."},{"usage":"Come to be unable to A, come to no longer be A","japanese":"君には時々我慢できなくなる。","reading":"きみにはときどきがまんできなくなる。","english":"Sometimes I can't stand you."}]},{"id":309,"level":"N3","expression":"ように言う","meaning":"Tell someone to do A","format":"Verb dictionary form / ない-form + ように言う","category":"Verb Forms & Conjugation","usages":[{"usage":"Tell someone to do A","japanese":"医者は彼に酒の量を減らすように言った。","reading":"いしゃはかれにさけのりょうをへらすようにいった。","english":"His doctor told him to cut down on drinking."}]},{"id":310,"level":"N3","expression":"らしい","meaning":"I heard that A; it seems like A; it appears that A","format":"Plain-form clause + らしい; Noun + らしい","category":"Appearance & Possibility","usages":[{"usage":"I heard that A; it seems like A; it appears that A","japanese":"彼は大変眠いらしい。","reading":"かれはたいへんねむいらしい。","english":"He seems to be very sleepy."},{"usage":"Just like A; typical of A","japanese":"自分のことを考える前に人のことを考えるのはまさに彼女らしい。","reading":"じぶんのことをかんがえるまえにひとのことをかんがえるのはまさにかのじょらしい。","english":"It is just like her to think of others before thinking of herself."}]},{"id":311,"level":"N3","expression":"わけがない","meaning":"There's no reason for A (A should not be possible)","format":"Verb / い-adj plain + わけがない; Noun / な-adj + なわけがない","category":"Verb Forms & Conjugation","usages":[{"usage":"There's no reason for A (A should not be possible)","japanese":"彼氏はそんなことを言うわけがないよ！","reading":"かれしはそんなことをいうわけがないよ！","english":"There's no way my boyfriend would have said something like that!"}]},{"id":312,"level":"N3","expression":"わけだ","meaning":"As you'd expect, A; Of course, A","format":"Verb / い-adj plain + わけだ; Noun / な-adj + なわけだ","category":"Other Expressions","usages":[{"usage":"As you'd expect, A; Of course, A","japanese":"どうりでみち子は嫌がるわけだ。","reading":"どうりでみちこはいやがるわけだ。","english":"It's no surprise that Michiko doesn't like it."}]},{"id":313,"level":"N3","expression":"わけではない","meaning":"Although you may think A; that is not the case.","format":"Verb / い-adj plain + わけではない; Noun / な-adj + なわけではない","category":"Verb Forms & Conjugation","usages":[{"usage":"Although you may think A; that is not the case.","japanese":"魚は、目が開いているが起きているわけではない。","reading":"さかなは、めがあいているがおきているわけではない。","english":"For fish, having their eyes open doesn't necessarily mean they are awake."}]},{"id":314,"level":"N3","expression":"わけにはいかない","meaning":"Must not A","format":"Verb dictionary form + わけにはいかない; Verb ない-form + わけにはいかない (cannot avoid)","category":"Verb Forms & Conjugation","usages":[{"usage":"Must not A","japanese":"泊まりたいユースホステルは大人気なので予約なしでいくわけにはいかない！","reading":"とまりたいユースホステルはだいにんきなのでよやくなしでいくわけにはいかない！","english":"The youth hostel I'd like to stay at is very popular, so I must not go without a reservation."},{"usage":"Must A","japanese":"一緒に遊びたいけど、宿題をやらないわけにはいかないからなあ。","reading":"いっしょにあそびたいけど、しゅくだいをやらないわけにはいかないからなあ。","english":"I'd love to hang out together, but I have to do my homework, so..."}]},{"id":315,"level":"N3","expression":"割に","meaning":"Considering A, B (unexpected)","format":"Verb / い-adj plain + わりに; Noun + の / な-adj + な + わりに","category":"Particles & Connectors","usages":[{"usage":"Considering A, B (unexpected)","japanese":"お金がない割には意外と服装が派手だ。","reading":"おかねがないわりにはいがいとふくそうがはでだ。","english":"In contrast for someone with no money, your clothes are unexpectedly flashy."}]},{"id":316,"level":"N3","expression":"を","meaning":"Over A; across A; along A","format":"Noun + を + transitive verb; place + を + movement verb","category":"Particles & Connectors","usages":[{"usage":"Over A; across A; along A","japanese":"小川を歩いて渡った。","reading":"おがわをあるいてわたった。","english":"I crossed the small stream by foot."},{"usage":"A is the direct object of a transitive verb","japanese":"ミルクを飲みなさい！","reading":"ミルクをのみなさい！","english":"Drink the milk!"},{"usage":"Marks place of departure A","japanese":"彼らは今日東京を発つ。","reading":"かれらはきょうとうきょうをたつ。","english":"They will depart (from) Tokyo today."},{"usage":"Shows state A","japanese":"彼女は東京でシステムエンジニアをしている。","reading":"かのじょはとうきょうでシステムエンジニアをしている。","english":"She is a systems engineer in Tokyo."},{"usage":"Shows the cause A of the subject's emotions","japanese":"私達は彼の死を悲しんだ。","reading":"わたしたちはかれのしをかなしんだ。","english":"We mourned his death."}]},{"id":317,"level":"N3","expression":"んだって","meaning":"Used to report information A (often heard)","format":"Plain-form clause + んだって (reported speech); Noun / な-adj + なんだって","category":"Verb Forms & Conjugation","usages":[{"usage":"Used to report information A (often heard)","japanese":"彼らついに結婚するんだって。","reading":"かれらついにけっこんするんだって。","english":"I hear that they're finally getting married."}]},{"id":318,"level":"N3","expression":"上げる","meaning":"Just finished/completed A","format":"Verb ます-stem + 上げる (finish thoroughly)","category":"Other Expressions","usages":[{"usage":"Just finished/completed A","japanese":"１０時にパンが焼き上がります。","reading":"１０じにパンがやきあがります。","english":"The bread will be finished at 10 o'clock"}]},{"id":319,"level":"N3","expression":"代わり","meaning":"Not A, but B; B in place of A","format":"Verb / い-adj plain + 代わりに; Noun + の代わりに","category":"Other Expressions","usages":[{"usage":"Not A, but B; B in place of A","japanese":"入院したお母さんに代わって僕は夕食を作ります。","reading":"にゅういんしたおかあさんにかわってぼくはゆうしょくをつくります。","english":"In place of mother, who is in the hospital, I'll make dinner."},{"usage":"Instead of A, B; In exchange for A, B","japanese":"昨日風邪をひいたので仕事をする代わりに一人でテレビゲームをやりました。","reading":"きのうかぜをひいたのでしごとをするかわりにひとりでテレビゲームをやりました。","english":"Since I caught a cold yesterday, I played video games by myself instead of doing work."}]},{"id":320,"level":"N3","expression":"Passive","meaning":"Be A-ed (Passive tense), when the action is directed at the subject.","format":"Verb passive form: Group 1 -aれる; Group 2 -られる; する→される; 来る→来られる","category":"Other Expressions","usages":[{"usage":"Be A-ed (Passive tense), when the action is directed at the subject.","japanese":"この車は十年前に作られました。","reading":"このくるまはじゅうねんまえにつくられました。","english":"This car was made ten years ago."},{"usage":"A is done, A happens","japanese":"外で遊んでいる最中、雨に降られた！","reading":"そとであそんでいるさいちゅう、あめにふられた！","english":"While I was playing outside it started to rain!"},{"usage":"A does B","japanese":"彼が運転されました。","reading":"かれがうんてんされました。","english":"He drove."}]},{"id":321,"level":"N3","expression":"少しも〜ない","meaning":"Not (even a little) A","format":"少しも + negative predicate","category":"Verb Forms & Conjugation","usages":[{"usage":"Not (even a little) A","japanese":"冬は洗濯物が少しも乾かないなあ。","reading":"ふゆはせんたくものがすこしもかわかないなあ。","english":"The laundry doesn't dry at all in the winter."}]},{"id":322,"level":"N3","expression":"最中","meaning":"In the middle of A","format":"Verb ている + 最中に / Noun + の最中に","category":"Other Expressions","usages":[{"usage":"In the middle of A","japanese":"つまらない授業の最中寝つづけました。","reading":"つまらないじゅぎょうのさいちゅうねつづけました。","english":"I fell asleep in the middle of a boring lesson."}]},{"id":323,"level":"N3","expression":"決して〜ない","meaning":"Definitely won't A; definitely isn't A","format":"決して + negative predicate","category":"Verb Forms & Conjugation","usages":[{"usage":"Definitely won't A; definitely isn't A","japanese":"お味噌汁は決して沸かさないでよ、不味くなるから","reading":"おみそしるはけっしてわかさないでよ、まずくなるから","english":"Make sure you don't let the miso soup boil; it'll go bad!"}]},{"id":324,"level":"N3","expression":"的","meaning":"A-like, A-ish, In an A way","format":"Noun + 的(な) + Noun; Noun + 的に + Verb","category":"Other Expressions","usages":[{"usage":"A-like, A-ish, In an A way","japanese":"これはとても現実的な解決策だね。","reading":"これはとてもげんじつてきなかいけつさくだね。","english":"This is a very realistic solution."}]},{"id":325,"level":"N3","expression":"通す","meaning":"Continue to A, do A until the end","format":"Verb ます-stem + 通す (continue until the end)","category":"Other Expressions","usages":[{"usage":"Continue to A, do A until the end","japanese":"彼は自分の意志を貫き通した。","reading":"かれはじぶんのいしをつらぬきとおした。","english":"He stuck to his intentions until the end."}]},{"id":326,"level":"N3","expression":"通り／通り","meaning":"In the way A; The same as A, B; As described by A, B","format":"Verb た-form / dictionary form + 通り(に); Noun + の通り(に)","category":"Other Expressions","usages":[{"usage":"In the way A; The same as A, B; As described by A, B","japanese":"昨日の授業は試験があったけど、今日はいつも通り。","reading":"きのうのじゅぎょうはしけんがあったけど、きょうはいつもとおり。","english":"There was a test in class yesterday, but today it's business as usual."}]},{"id":327,"level":"N3","expression":"関して","meaning":"About A; With relation to A","format":"Noun + に関して / に関する + Noun","category":"Verb Forms & Conjugation","usages":[{"usage":"About A; With relation to A","japanese":"登校しない子供に関しては、両親と相談することです。","reading":"とうこうしないこどもにかんしては、りょうしんとそうだんすることです。","english":"Regarding the children that aren't attending school, that is something to be discussed with the parents."}]}];
